window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[269]={"id":"269","numero":269,"titre":"Douleur abdominale aiguë","objectifs":[{"id":"269-1","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier une douleur abdominale chez l’enfant","contenu":"<p>La <span class=\"kw-clinique\">douleur abdominale</span> est l'un des premiers motifs de consultation pédiatrique. La <strong>difficulté centrale</strong> : plus l'enfant est jeune, moins il verbalise — le diagnostic repose alors sur l'<span class=\"kw-clinique\">interrogatoire des parents</span> et l'observation du comportement.</p>\n\n      <h5>Reconnaître la douleur selon l'âge</h5>\n      <table >\n        <thead>\n          <tr>\n            <th>Âge</th>\n            <th>Comment la douleur se manifeste</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Nourrisson</strong> (ne verbalise pas)</td>\n            <td><span class=\"kw-clinique\">Accès de pleurs / cris</span>, agitation, irritabilité ; <span class=\"kw-clinique\">pâleur</span>, refus du biberon ; attitude jambes repliées sur l'abdomen ; troubles du sommeil</td>\n          </tr>\n          <tr>\n            <td><strong>Jeune enfant</strong></td>\n            <td>Montre volontiers la <span class=\"kw-clinique\">région ombilicale</span> quelle que soit la cause → siège peu spécifique ; pleurs, position <span class=\"kw-ttt\">antalgique</span>, refus de jouer</td>\n          </tr>\n          <tr>\n            <td><strong>Grand enfant / adolescent</strong></td>\n            <td>Verbalise le siège, le type et l'horaire — interrogatoire proche de celui de l'adulte</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5 style=\"margin-top: 1.2em;\">Caractériser la douleur</h5>\n      <p>Préciser : <span class=\"kw-clinique\">mode d'installation</span>, durée (aiguë <span class=\"kw-chiffre\">&lt; 1 semaine</span> <span class=\"kw-bio\">vs</span> récurrente / chronique), intensité, siège, <span class=\"kw-clinique\">irradiation</span>, facteurs déclenchants et calmants, horaire.</p>\n      <p><strong>Signes d'accompagnement à rechercher systématiquement :</strong> <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-alerte\">vomissements (préciser s'ils sont bilieux)</span> ; troubles du transit (<span class=\"kw-clinique\">diarrhée</span>, arrêt des matières et des gaz) ; <span class=\"kw-clinique\">rectorragies</span> ; signes urinaires ; signes ORL et respiratoires.</p>\n\n      <h5 style=\"margin-top: 1.2em;\">Examen clinique</h5>\n      <p>Enfant <strong>déshabillé</strong>, mis en confiance, examiné avec des mains réchauffées. Palpation douce à la recherche d'une <span class=\"kw-alerte\">défense ou d'une contracture</span>, d'une <span class=\"kw-clinique\">masse</span>, d'une douleur provoquée. Ne jamais oublier l'<span class=\"kw-clinique\">examen des orifices herniaires</span> et des <span class=\"kw-clinique\">bourses</span> (torsion testiculaire). Le TR n'est pas systématique chez l'enfant.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège — la douleur projetée.</strong> Une <span class=\"kw-etio\">pneumopathie de la base</span>, une angine, une otite ou une adénolymphite mésentérique peuvent se révéler par une <span class=\"kw-clinique\">douleur abdominale</span> : l'examen doit toujours être complet (ORL, pulmonaire).\n      </div>\n\n      <h5 style=\"margin-top: 1.2em;\">Organique <span class=\"kw-bio\">vs</span> fonctionnel — critères d'orientation</h5>\n      <table >\n        <thead>\n          <tr>\n            <th>Critère</th>\n            <th>Origine <span class=\"kw-alerte\">organique</span></th>\n            <th>Origine fonctionnelle</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Localisation</strong></td>\n            <td><span class=\"kw-clinique\">Précise, latéralisée</span> (loin de l'ombilic)</td>\n            <td>Péri-ombilicale</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Irradiation</span></strong></td>\n            <td>Oui</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Rythme</strong></td>\n            <td>Continu</td>\n            <td>Sporadique</td>\n          </tr>\n          <tr>\n            <td><strong>Horaire</strong></td>\n            <td>Diurne, <span class=\"kw-alerte\">nocturne (réveille l'enfant)</span></td>\n            <td>Diurne, parfois nocturne</td>\n          </tr>\n          <tr>\n            <td><strong>Intensité</strong></td>\n            <td>Sans valeur d'orientation</td>\n            <td>Sans valeur d'orientation (souvent intense)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">AEG</span></strong></td>\n            <td>Souvent (<span class=\"kw-clinique\">perte de poids</span>, retard de croissance, retard pubertaire)</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td><span class=\"kw-alerte\">Diarrhée nocturne, rectorragies, hématémèse</span> ; symptômes extra-digestifs (<span class=\"kw-clinique\">fièvre</span>, arthralgies, rash cutané, aphtes buccaux)</td>\n            <td>Examen abdominal normal ; pas de signes associés</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 274 — <span class=\"kw-clinique\">Vomissements</span> · 286 — <span class=\"kw-clinique\">Diarrhée</span> aiguë - <span class=\"kw-clinique\">déshydratation</span> · 283 — <span class=\"kw-clinique\">Constipation</span></em></p>","frequence":0},{"id":"269-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les étiologies des douleurs abdominales chez le nourrisson et l’enfant","contenu":"<p>Le raisonnement étiologique pédiatrique est <strong>guidé par l'âge</strong> : à chaque tranche d'âge correspondent des causes chirurgicales et médicales privilégiées. Règle d'or : <span class=\"kw-alerte\">toujours éliminer une urgence chirurgicale</span> avant de retenir une cause bénigne.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Âge</th>\n            <th>Causes chirurgicales</th>\n            <th>Causes médicales</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Nouveau-né</strong> (&lt; <span class=\"kw-chiffre\">1 mois</span>)</td>\n            <td><span class=\"kw-alerte\">Hernie inguinale étranglée</span> ; <span class=\"kw-alerte\">volvulus sur malrotation du grêle</span> ; <span class=\"kw-alerte\">occlusions néonatales</span> (atrésie intestinale, malformation ano-rectale, <span class=\"kw-clinique\">iléus</span> / bouchon méconial — mode de révélation de la <span class=\"kw-etio\">mucoviscidose</span>) ; <span class=\"kw-alerte\">maladie de Hirschsprung</span> ; <span class=\"kw-alerte\">ECUN</span> (entérocolite ulcéro-nécrosante du prématuré ++)</td>\n            <td>Coliques du nourrisson ; <span class=\"kw-ci\">allergie</span> aux protéines de lait de vache ; <strong>traumatisme</strong> (suspecter une <span class=\"kw-alerte\">maltraitance</span> avant l'âge de la marche)</td>\n          </tr>\n          <tr>\n            <td><strong>Nourrisson</strong> (<span class=\"kw-chiffre\">1 mois</span> –<span class=\"kw-chiffre\"> 2 ans</span>)</td>\n            <td><span class=\"kw-etio\">Invagination intestinale aiguë</span> ++ ; <span class=\"kw-alerte\">hernie inguinale étranglée</span> ; volvulus sur malrotation du grêle ; sténose hypertrophique du pylore (<span class=\"kw-clinique\">vomissements</span> &gt; douleur) ; <span class=\"kw-alerte\">torsion testiculaire</span> (forme extra-vaginale)</td>\n            <td>Gastro-entérite aiguë ; coliques du nourrisson (bénin, &lt; <span class=\"kw-chiffre\">5 mois</span>) ; <span class=\"kw-ci\">allergie</span> aux protéines de lait de vache ; erreurs diététiques ; infection (ORL, urinaire, pulmonaire) ; <span class=\"kw-etio\">adénolymphite mésentérique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Enfant</strong> (<span class=\"kw-chiffre\">2-12 ans</span>)</td>\n            <td><span class=\"kw-etio\">Appendicite aiguë</span> ++ (1ʳᵉ cause chirurgicale après <span class=\"kw-chiffre\">2 ans</span> ; pic <span class=\"kw-chiffre\">7-13 ans</span> ; <strong>toujours compliquée avant <span class=\"kw-chiffre\">6 ans</span></strong>) ; invagination intestinale aiguë (encore possible) ; hernie étranglée ; <span class=\"kw-etio\">diverticule de Meckel</span> ; <span class=\"kw-alerte\">torsion testiculaire ou d'annexe</span></td>\n            <td>Gastro-entérite aiguë ; <span class=\"kw-etio\">adénolymphite mésentérique</span> (DD de l'<span class=\"kw-clinique\">appendicite</span>, contexte <span class=\"kw-etio\">viral</span> / ORL) ; <span class=\"kw-clinique\">constipation</span> ++ ; <span class=\"kw-clinique\">douleurs abdominales fonctionnelles</span> ; pneumopathie de la base ; <span class=\"kw-etio\">infection urinaire</span> ; angine ; <span class=\"kw-etio\">migraine abdominale</span> ; <span class=\"kw-etio\">crise vaso-occlusive de drépanocytose</span> ; <span class=\"kw-etio\">purpura rhumatoïde</span> ; <span class=\"kw-etio\">acidocétose diabétique</span> ; <span class=\"kw-etio\">MICI</span> ; pancréatite ; <span class=\"kw-alerte\">syndrome hémolytique et urémique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Adolescent</strong> (&gt;<span class=\"kw-chiffre\"> 12 ans</span>)</td>\n            <td><span class=\"kw-etio\">Appendicite</span> ; <span class=\"kw-alerte\">torsion testiculaire</span> (garçon ; pic <span class=\"kw-chiffre\">12-18 ans</span>) ; <span class=\"kw-alerte\">torsion d'annexe / kyste ovarien compliqué</span> (fille) ; hernie étranglée ; <span class=\"kw-clinique\">cholécystite</span> ; lithiase biliaire / urinaire ; hématosalpinx ; <span class=\"kw-alerte\">GEU</span> ; salpingite</td>\n            <td>Causes gynécologiques de la fille : <span class=\"kw-etio\">dysménorrhée</span>, <span class=\"kw-etio\">douleurs ovulatoires</span>, <span class=\"kw-ci\">grossesse</span> extra-utérine, salpingite ; <span class=\"kw-clinique\">ulcère gastro-duodénal</span> ; <span class=\"kw-etio\">MICI</span> (<span class=\"kw-etio\">maladie de Crohn</span>) ; <span class=\"kw-clinique\">douleurs abdominales</span> fonctionnelles récurrentes ; <span class=\"kw-etio\">migraine abdominale</span> ; <span class=\"kw-etio\">crise vaso-occlusive de drépanocytose</span> ; pancréatite ; <span class=\"kw-clinique\">RGO</span> ; <span class=\"kw-etio\">diabète</span> ; <span class=\"kw-etio\">mucoviscidose</span> ; <span class=\"kw-ci\">intolérance</span> au lactose ; intoxications aiguës / overdose</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-clinique\">Les</span> 5 urgences chirurgicales à éliminer à tout âge.</strong> <span class=\"kw-clinique\">Appendicite</span> · invagination intestinale aiguë · hernie étranglée · volvulus sur malrotation · torsion testiculaire ou d'annexe — auxquelles s'ajoute toute occlusion ou péritonite.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Ne pas oublier <span class=\"kw-clinique\">les</span> causes médicales « pièges ».</strong> L'<span class=\"kw-etio\">acidocétose diabétique</span> peut se révéler par un tableau pseudo-chirurgical : une <span class=\"kw-bio\">glycémie capillaire</span> doit être systématique devant une <span class=\"kw-clinique\">douleur abdominale</span> fébrile ou avec <span class=\"kw-clinique\">vomissements</span> inexpliqués.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 356 — <span class=\"kw-clinique\">Appendicite</span> · 354 — Syndrome occlusif · 289 — Hernie pariétale · 215 — <span class=\"kw-def\">Purpura</span> · 247 — <span class=\"kw-def\">Diabète</span> · 286 — <span class=\"kw-clinique\">Diarrhée</span> aiguë - <span class=\"kw-clinique\">déshydratation</span></em></p>","frequence":0},{"id":"269-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les examens nécessaires chez l’enfant","contenu":"<p>Principe directeur : <strong>aucun bilan systématique exhaustif</strong> — <span class=\"kw-clinique\">les</span> examens sont <span class=\"kw-clinique\">orientés par la clinique</span>, et l'imagerie privilégie les techniques <strong>non irradiantes</strong>.</p>\n\n      <h5>Bilan <span class=\"kw-ttt\">biologique</span></h5>\n      <table >\n        <thead>\n          <tr>\n            <th>Indication</th>\n            <th>Examens</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Selon le contexte</strong></td>\n            <td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span> (<span class=\"kw-def\">syndrome inflammatoire</span> : <span class=\"kw-clinique\">appendicite</span>, adénolymphite) ; <span class=\"kw-bio\">ionogramme sanguin</span> + <span class=\"kw-bio\">créatinine</span> si <span class=\"kw-clinique\">vomissements</span> / <span class=\"kw-clinique\">déshydratation</span> ; <span class=\"kw-bio\">bilan hépatique</span> + <span class=\"kw-bio\">lipasémie</span> si douleur de l'hypochondre droit ou ép<span class=\"kw-chiffre\">iga</span>strique ; <span class=\"kw-bio\">gaz du sang</span> si suspicion d'acidocétose</td>\n          </tr>\n          <tr>\n            <td><strong>Réflexes à ne pas manquer</strong></td>\n            <td><span class=\"kw-bio\">Bandelette urinaire</span> systématique (l'<span class=\"kw-etio\">infection urinaire</span> est un grand piège) ; <span class=\"kw-bio\">glycémie capillaire</span> ou veineuse (<span class=\"kw-alerte\">acidocétose</span>) ; <span class=\"kw-bio\">β-HCG</span> chez l'adolescente</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5 style=\"margin-top: 1.2em;\">Imagerie</h5>\n      <table >\n        <thead>\n          <tr>\n            <th>Examen</th>\n            <th>Place chez l'enfant</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échographie abdominale</span></td>\n            <td><strong>Examen de 1ʳᵉ intention ++</strong> (non irradiant) : <span class=\"kw-etio\">appendicite</span>, <span class=\"kw-etio\">invagination intestinale aiguë</span>, <span class=\"kw-etio\">sténose hypertrophique du pylore</span>, <span class=\"kw-etio\">volvulus sur malrotation</span>, torsion testiculaire ou d'annexe, <span class=\"kw-etio\">colique néphrétique</span>, bilan de <span class=\"kw-etio\">pyélonéphrite</span> (sous <span class=\"kw-chiffre\">48 h</span>), <span class=\"kw-clinique\">douleurs abdominales récidivantes</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">ASP</span></td>\n            <td>Indications limitées : <strong>1ʳᵉ intention</strong> en cas d'<span class=\"kw-clinique\">ingestion de corps étranger radio-opaque</span> ; <strong>2ⁿᵈ intention</strong> après <span class=\"kw-imagerie\">échographie</span> si jugé nécessaire par le radiologue (suspicion d'<span class=\"kw-alerte\">occlusion</span>, de <span class=\"kw-alerte\">perforation</span> / pneumopéritoine)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Radiographie de thorax</span></td>\n            <td>Si <span class=\"kw-clinique\">polypnée</span> fébrile / suspicion de <span class=\"kw-etio\">pneumopathie de la base</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM</span></td>\n            <td>À limiter (<span class=\"kw-clinique\">irradiation</span>) — réservée aux situations complexes ou au doute persistant</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Le maître mot pédiatrique.</strong> <span class=\"kw-imagerie\">Échographie en 1ʳᵉ intention</span>, limiter l'<span class=\"kw-clinique\">irradiation</span>. La <span class=\"kw-bio\">bandelette urinaire</span> est un réflexe devant toute <span class=\"kw-clinique\">douleur abdominale</span> fébrile de l'enfant.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 356 — <span class=\"kw-clinique\">Appendicite</span> · 247 — <span class=\"kw-def\">Diabète</span> · 354 — Syndrome occlusif</em></p>","frequence":1},{"id":"269-4","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier une urgence chirurgicale ou médicale chez l’enfant","contenu":"<p>Devant une <span class=\"kw-clinique\">douleur abdominale</span> de l'enfant, le premier réflexe est de <strong>rechercher <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">signes de gravité</span></strong> qui imposent une prise en charge urgente.</p>\n\n      <h5><span class=\"kw-alerte\">Drapeaux rouges</span></h5>\n      <table >\n        <thead>\n          <tr>\n            <th>Domaine</th>\n            <th>Signes d'alerte</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td><span class=\"kw-alerte\">Prématuré</span>, <span class=\"kw-alerte\">nouveau-né</span>, <span class=\"kw-alerte\">nourrisson</span> ; maladie chronique invalidante ; handicap</td>\n          </tr>\n          <tr>\n            <td><strong>Contexte</strong></td>\n            <td>Traumatisme à haute cinétique ; chute d'une hauteur élevée ; polytraumatisme ; <span class=\"kw-alerte\">suspicion de maltraitance</span> (traumatisme univoque, surtout <strong>avant l'âge de la marche</strong>)</td>\n          </tr>\n          <tr>\n            <td><strong>Douleur</strong></td>\n            <td>Début <span class=\"kw-alerte\">brutal</span> puis permanente, intense, diurne <strong>et nocturne</strong> (réveillant l'enfant)</td>\n          </tr>\n          <tr>\n            <td><strong>Digestif</strong></td>\n            <td><span class=\"kw-alerte\">Vomissements bilieux (verts)</span> ; <span class=\"kw-alerte\">méléna</span> ; <span class=\"kw-clinique\">rectorragies</span> ; arrêt des matières et des gaz ; météorisme</td>\n          </tr>\n          <tr>\n            <td><strong>Examen</strong></td>\n            <td><span class=\"kw-alerte\">Défense, contracture</span>, douleur à la décompression ; <span class=\"kw-clinique\">masse</span> abdominale palpable ; <span class=\"kw-alerte\">tuméfaction inguinale ou scrotale douloureuse</span> (hernie non réductible, grosse bourse aiguë) ; <span class=\"kw-alerte\">plaie pénétrante</span></td>\n          </tr>\n          <tr>\n            <td><strong>État général</strong></td>\n            <td><span class=\"kw-clinique\">Altération de l'état général</span> (perte de poids) ; teint gris, geignement, hypotonie ; signes de <span class=\"kw-alerte\">choc</span> ou de <span class=\"kw-clinique\">déshydratation</span> ; syndrome polyuro-polydipsique ; <span class=\"kw-clinique\">dyspnée</span> ; signes d'<span class=\"kw-alerte\">anaphylaxie</span> ; troubles de conscience</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5 style=\"margin-top: 1.2em;\">Urgences chirurgicales</h5>\n      <p><span class=\"kw-etio\">Appendicite</span> · <span class=\"kw-etio\">invagination intestinale aiguë</span> · <span class=\"kw-alerte\">hernie inguinale étranglée</span> · <span class=\"kw-etio\">volvulus sur malrotation</span> · <span class=\"kw-alerte\">torsion testiculaire ou d'annexe</span> · <span class=\"kw-alerte\">occlusion</span> · <span class=\"kw-alerte\">péritonite</span> · <span class=\"kw-clinique\">diverticule</span> de Meckel compliqué.</p>\n\n      <h5 style=\"margin-top: 1.2em;\">Urgences médicales</h5>\n      <p><span class=\"kw-etio\">Acidocétose diabétique</span> (la <span class=\"kw-clinique\">douleur abdominale</span> en est un mode de révélation fréquent) · <span class=\"kw-etio\">purpura rhumatoïde</span> compliqué (peut induire une invagination) · <span class=\"kw-alerte\">syndrome hémolytique et urémique</span> (<span class=\"kw-clinique\">diarrhée</span> glairo-sanglante puis <span class=\"kw-clinique\">pâleur</span> + <span class=\"kw-clinique\">oligurie</span>) · <span class=\"kw-alerte\">sepsis</span> · <span class=\"kw-alerte\">insuffisance surrénale aiguë</span>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Réflexes vitaux.</strong> Des <span class=\"kw-alerte\">vomissements bilieux</span> chez un nourrisson = occlusion / volvulus jusqu'à preuve du contraire → imagerie et avis chirurgical en <span class=\"kw-alerte\">urgence</span>. Toute <span class=\"kw-clinique\">douleur abdominale</span> du garçon impose l'<span class=\"kw-clinique\">examen des bourses</span> : une torsion testiculaire doit être opérée en moins de <span class=\"kw-chiffre\">6 h</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 356 — <span class=\"kw-clinique\">Appendicite</span> · 354 — Syndrome occlusif · 357 — Péritonite aiguë · 247 — <span class=\"kw-def\">Diabète</span></em></p>","frequence":0},{"id":"269-5","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes cliniques et examens complémentaires en faveur d’une invagination intestinale aiguë","contenu":"<p>L'<span class=\"kw-etio\">invagination intestinale aiguë (IIA)</span> est le télescopage d'un segment intestinal d'amont dans le segment d'aval. C'est une <span class=\"kw-alerte\">urgence</span> : non traitée, elle évolue vers l'occlusion, la <span class=\"kw-clinique\">nécrose</span> <span class=\"kw-etio\">ischémique</span>, la perforation et le <span class=\"kw-alerte\">choc</span>.</p>\n\n      <h5>Deux formes selon l'âge</h5>\n      <table >\n        <thead>\n          <tr>\n            <th>Forme</th>\n            <th><span class=\"kw-def\">Terrain</span> &amp; mécanisme</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Idiopathique du nourrisson</strong> (la plus fréquente)</td>\n            <td><span class=\"kw-chiffre\">2 mois – 2 ans</span> (<strong>pic <span class=\"kw-chiffre\">9 mois</span></strong>) ; contexte post-<span class=\"kw-etio\">viral</span> (hypertrophie des plaques de Peyer / <span class=\"kw-etio\">adénolymphite mésentérique</span> faisant tête d'invagination → hyperpéristaltisme) ; siège <strong>iléo-cæcal ++</strong> (transvalvulaire, ou avec cæcum et appendice invaginés dans le côlon droit) ; forme <span class=\"kw-clinique\">iléo-iléale</span> possible</td>\n          </tr>\n          <tr>\n            <td><strong>Secondaire</strong></td>\n            <td>Enfant plus grand ou hors tranche d'âge typique → rechercher une <span class=\"kw-alerte\">lésion organique</span> : <span class=\"kw-etio\">diverticule de Meckel</span>, polype, lymphome, <span class=\"kw-etio\">purpura rhumatoïde</span>, <span class=\"kw-etio\">mucoviscidose</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5 style=\"margin-top: 1.2em;\">Signes cliniques — triade classique (rarement complète)</h5>\n      <table >\n        <thead>\n          <tr>\n            <th>Signe</th>\n            <th>Description</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Douleurs paroxystiques</span></td>\n            <td>Crises brutales : pleurs, cris, <span class=\"kw-clinique\">pâleur</span>, hypotonie, refus du biberon, jambes repliées — <strong>entrecoupées d'intervalles libres</strong> (enfant calme entre <span class=\"kw-clinique\">les</span> crises)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Vomissements</span></td>\n            <td>Souvent précoces, d'abord alimentaires</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Rectorragies</span></td>\n            <td>Sang rouge / « <strong>gelée de groseille</strong> » — signe <strong>tardif</strong>, témoin de la souffrance <span class=\"kw-etio\">ischémique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Autres signes :</strong> <span class=\"kw-alerte\">somnolence / hypotonie entre les crises</span> (forme neurologique trompeuse) ; <span class=\"kw-clinique\">boudin d'invagination</span> palpable (<span class=\"kw-clinique\">masse</span> allongée, mobile — pas toujours perceptible) ; <span class=\"kw-clinique\">douleur de l'hypochondre droit</span> le plus souvent à la palpation ; fosse iliaque droite déshabitée (<span class=\"kw-clinique\">signe de Dance</span>) ; <span class=\"kw-clinique\">toucher rectal</span> pouvant extérioriser du sang (non systématique).</p>\n\n      <h5 style=\"margin-top: 1.2em;\">Examens complémentaires</h5>\n      <table >\n        <thead>\n          <tr>\n            <th>Examen</th>\n            <th>Apport</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échographie abdominale</span></td>\n            <td><strong>Examen clé, 1ʳᵉ intention</strong> : image en <span class=\"kw-imagerie\">cocarde / cible</span> (coupe transversale), image en <span class=\"kw-imagerie\">sandwich / pseudo-rein</span> (coupe longitudinale)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">ASP</span></td>\n            <td>Peu contributif : opacité de l'hypochondre droit, signes d'occlusion éventuels</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Lavement</span> (<span class=\"kw-imagerie\">opaque</span>, <span class=\"kw-imagerie\">hydrosoluble</span> ou <span class=\"kw-imagerie\">pneumatique</span>)</td>\n            <td>Valeur <strong>diagnostique ET thérapeutique</strong> (<span class=\"kw-ttt\">réduction</span> de l'invagination)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Conduite à tenir.</strong> En l'absence de <span class=\"kw-alerte\">signe de gravité</span> ou de perforation → <span class=\"kw-imagerie\">réduction par lavement</span> sous contrôle radiologique ou échographique. <span class=\"kw-alerte\">Chirurgie</span> si échec du lavement, perforation, <span class=\"kw-clinique\">péritonite</span>, <span class=\"kw-alerte\">choc</span>, ou forme secondaire avec <span class=\"kw-clinique\">lésion</span> identifiée.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 354 — Syndrome occlusif · 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë · 215 — <span class=\"kw-def\">Purpura</span></em></p>","frequence":1},{"id":"269-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques de l’interrogatoire et de l’examen clinique face à une douleur abdominale aiguë","contenu":"<p>Une <span class=\"kw-clinique\">douleur abdominale</span> est dite <span class=\"kw-def\">aiguë</span> lorsqu'elle évolue depuis <span class=\"kw-chiffre\">&lt; 1 semaine</span>. En pratique, une <span class=\"kw-clinique\">douleur viscérale</span> est le plus souvent localisée à une région, rarement à un point précis ; la douleur digestive d'un <span class=\"kw-clinique\">organe creux</span> est volontiers paroxystique, à type de crampes.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Caractère de la douleur</th>\n            <th>Orientation étiologique</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Exacerbée par la marche, l'inspiration profonde ; calmée par le décubitus</span></td>\n            <td><span class=\"kw-etio\">Foyer inflammatoire intra-abdominal irritant le péritoine</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Aggravée par le repas</span></td>\n            <td><span class=\"kw-etio\">Pancréatite</span> ; <span class=\"kw-etio\">angor mésentérique</span> ; <span class=\"kw-etio\">colique hépatique</span> ; <span class=\"kw-etio\">cancer gastrique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Soulagée par l'alimentation</span></td>\n            <td><span class=\"kw-etio\">Ulcère gastro-duodénal</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Soulagée par l'antéflexion</span></td>\n            <td><span class=\"kw-etio\">Douleur pancréatique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Soulagée par le vomissement</span></td>\n            <td><span class=\"kw-etio\">Syndrome occlusif</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Silence auscultatoire de l'abdomen</span></td>\n            <td><span class=\"kw-alerte\">Occlusion par strangulation</span> ; <span class=\"kw-alerte\">ischémie intestinale</span> ; <span class=\"kw-etio\">iléus paralytique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Bruits hydro-aériques intenses</span></td>\n            <td><span class=\"kw-etio\">Obstacle incomplet</span> (<span class=\"kw-clinique\">syndrome de Koenig</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Localisation</th>\n            <th>Organes et causes à évoquer</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Ép<span class=\"kw-chiffre\">iga</span>stre</strong></td>\n            <td>Estomac ; pancréas ; foie et <span class=\"kw-clinique\">vésicule</span> biliaire ; côlon<br><strong>Hors digestif :</strong> <span class=\"kw-alerte\">cause cardiaque</span> ; cause vasculaire</td>\n          </tr>\n          <tr>\n            <td><strong>Hypochondre droit</strong></td>\n            <td>Foie et <span class=\"kw-clinique\">vésicule</span> biliaire ; côlon ; voies urinaires ; cause pleuro-pulmonaire</td>\n          </tr>\n          <tr>\n            <td><strong>Hypochondre gauche</strong></td>\n            <td>Pancréas caudal ; rate ; côlon ; voies urinaires ; cause pleuro-pulmonaire</td>\n          </tr>\n          <tr>\n            <td><strong>Flanc droit</strong></td>\n            <td>Côlon ; intestin grêle ; voies urinaires ; causes gynécologiques</td>\n          </tr>\n          <tr>\n            <td><strong>Flanc gauche</strong></td>\n            <td>Côlon ; intestin grêle ; voies urinaires ; causes gynécologiques</td>\n          </tr>\n          <tr>\n            <td><strong>Fosse iliaque droite</strong></td>\n            <td>Côlon ; appendice ; iléon (intestin grêle) ; causes gynécologiques</td>\n          </tr>\n          <tr>\n            <td><strong>Fosse iliaque gauche</strong></td>\n            <td>Côlon (diverticules) ; intestin grêle ; causes gynécologiques</td>\n          </tr>\n          <tr>\n            <td><strong>Hypogastre</strong></td>\n            <td>Côlon ; vessie et prostate (homme) ; causes gynécologiques (femme)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr>\n            <th><span class=\"kw-clinique\">Irradiation</span></th>\n            <th>Causes possibles</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Rétrosternale</strong></td>\n            <td><span class=\"kw-clinique\">RGO</span> ; trouble moteur œsophagien ; <span class=\"kw-alerte\">syndrome coronarien aigu</span> (à confondre avec une douleur cardiaque → évaluation rapide)</td>\n          </tr>\n          <tr>\n            <td><strong>Épaule / omoplate droite</strong></td>\n            <td><span class=\"kw-etio\">Douleur biliaire</span> (<span class=\"kw-clinique\">cholécystite</span>) ; <span class=\"kw-etio\">colique hépatique</span><br><strong>Mécanisme :</strong> projection via l'innervation du diaphragme par le nerf phrénique</td>\n          </tr>\n          <tr>\n            <td><strong>Postérieure (dos), en ceinture</strong></td>\n            <td><span class=\"kw-etio\">Pancréatite aiguë</span></td>\n          </tr>\n          <tr>\n            <td><strong>Organes génitaux externes</strong></td>\n            <td><span class=\"kw-etio\">Colique néphrétique</span> (migration du calcul du flanc vers <span class=\"kw-clinique\">les</span> OGE le long de l'uretère)</td>\n          </tr>\n          <tr>\n            <td><strong>Psoas / organes génitaux externes</strong></td>\n            <td><span class=\"kw-etio\">Appendicite</span> (irritation du muscle psoas par un appendice <span class=\"kw-etio\">inflammatoire</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5 style=\"margin-top: 1.2em;\">Causes médicales à ne pas méconnaître</h5>\n      <p>Point fort EDN : une cause <strong>médicale</strong> peut mimer un abdomen chirurgical. Le réflexe paraclinique devant une douleur médicale inexpliquée inclut <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">calcémie</span> et <span class=\"kw-bio\">glycémie</span>.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Cause</th>\n            <th><span class=\"kw-def\">Terrain</span> / déclencheur</th>\n            <th>Indices</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Infarctus du myocarde inférieur</span></td>\n            <td><span class=\"kw-def\">Facteurs de risque</span> cardiovasculaire</td>\n            <td>Douleur ép<span class=\"kw-chiffre\">iga</span>strique → <strong><span class=\"kw-bio\">ECG</span> systématique</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Insuffisance surrénale aiguë</span> (<span class=\"kw-alerte\">urgence</span> médicale)</td>\n            <td>Insuffisance surrénale chronique connue ; <span class=\"kw-ttt\">corticoïdes</span> au long cours interrompus ; post-partum</td>\n            <td>Douleurs intenses et diffuses <strong>MAIS abdomen souple + TR indolore</strong> ; <span class=\"kw-bio\">hyponatrémie</span> ; <span class=\"kw-bio\">hyperkaliémie</span> ; <span class=\"kw-bio\">hypoglycémie</span> ; <span class=\"kw-bio\">cortisolémie effondrée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Acidocétose diabétique</span></td>\n            <td><span class=\"kw-def\">Diabète</span> connu ou situation révélatrice</td>\n            <td>Syndrome polyuro-polydipsique ; <span class=\"kw-clinique\">dyspnée</span> de Kussmaul ; haleine cétosique ; <span class=\"kw-bio\">hyperglycémie + cétonurie + acidose</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Acidocétose alcoolique</span></td>\n            <td><span class=\"kw-etio\">Alcoolisme</span> chronique + jeûne prolongé avec poursuite de la consommation</td>\n            <td><span class=\"kw-clinique\">Vomissements</span> incoercibles ; <span class=\"kw-bio\">acidose métabolique à trou anionique élevé</span> ; <span class=\"kw-bio\">glycémie</span> subnormale ou basse</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Maladie périodique</span> (<span class=\"kw-clinique\">fièvre</span> méditerranéenne familiale)</td>\n            <td>Populations du pourtour méditerranéen ; début <span class=\"kw-chiffre\">&lt; 20 ans</span> dans <span class=\"kw-chiffre\">85 %</span> des cas</td>\n            <td><span class=\"kw-clinique\">Fièvre</span> intermittente <span class=\"kw-chiffre\">~36 h</span> contemporaine des douleurs ; <span class=\"kw-clinique\">arthralgies</span> ; sérites ; mutation du gène <strong>MEFV</strong> ; traitement par <span class=\"kw-ttt\">colchicine</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Porphyrie hépatique aiguë intermittente</span></td>\n            <td>Femme jeune en période d'activité génitale ; crise favorisée par infection ou médicament</td>\n            <td>Douleurs intenses + manifestations neurologiques / psychiatriques ; <span class=\"kw-clinique\">urines rouge-porto</span> ; dosage urinaire <span class=\"kw-bio\">ALA + PBG</span> très élevés</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Angio-œdème bradykinique</span></td>\n            <td>Médicaments : <span class=\"kw-ttt\">IEC</span>, <span class=\"kw-ttt\">ARA2</span>, <span class=\"kw-ttt\">gliptines</span> ; déficit en C1-inhibiteur (<span class=\"kw-etio\">héréditaire</span> ou acquis)</td>\n            <td><span class=\"kw-clinique\">Œdème</span> mou, blanc, transitoire ; <strong>pas d'<span class=\"kw-clinique\">urticaire</span> ni de <span class=\"kw-clinique\">prurit</span></strong> ; météorisme + douleurs diffuses ; <strong>ne répond pas aux anti-<span class=\"kw-chiffre\">H1</span> ni aux <span class=\"kw-ttt\">corticoïdes</span></strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Périhépatite (syndrome de Fitz-Hugh-Curtis)</span></td>\n            <td>Femme ; <span class=\"kw-clinique\">IST</span> — Chlamydia (<span class=\"kw-chiffre\">80 %</span>), <span class=\"kw-clinique\">gonocoque</span> (<span class=\"kw-chiffre\">20 %</span>)</td>\n            <td>Douleurs de l'hypochondre droit ± <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-def\">syndrome inflammatoire</span> ; adhérences péritonéales « en cordes de violon »</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Purpura rhumatoïde</span></td>\n            <td>Enfant surtout</td>\n            <td>Douleurs d'<span class=\"kw-clinique\">évolution</span> spontanément favorable ; <span class=\"kw-clinique\">purpura + arthralgies + atteinte rénale</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Saturnisme</span> (intoxication au plomb)</td>\n            <td>Eau de canalisations défectueuses ; peintures au plomb</td>\n            <td>Tableau proche de la crise de porphyrie ; dosage de la <span class=\"kw-bio\">plombémie</span> et de la <span class=\"kw-bio\">plomburie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Hypercalcémie aiguë</span> (<span class=\"kw-alerte\">urgence</span> médicale)</td>\n            <td>Contexte évocateur (néoplasie, hyperparathyroïdie)</td>\n            <td>Tableau abdominal pseudo-chirurgical ; dosage de la <span class=\"kw-bio\">calcémie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Syndrome TRAPS</span> (<span class=\"kw-clinique\">fièvre</span> auto-<span class=\"kw-etio\">inflammatoire</span>)</td>\n            <td>Sujets originaires du nord de l'Europe ; anomalie du récepteur au TNF</td>\n            <td><span class=\"kw-clinique\">Douleurs abdominales</span> récurrentes + épisodes de <span class=\"kw-clinique\">fièvre</span> prolongée ; parfois syndrome pseudo-appendiculaire ; mutation du gène <strong>TNFRSF1A</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Syndrome hyper-IgD</span> (<span class=\"kw-clinique\">fièvre</span> auto-<span class=\"kw-etio\">inflammatoire</span>)</td>\n            <td>Maladie auto-<span class=\"kw-etio\">inflammatoire</span> héréditaire</td>\n            <td><span class=\"kw-clinique\">Douleurs abdominales</span> fébriles récurrentes + <span class=\"kw-clinique\">diarrhée</span> + douleurs articulaires ; dosage des <span class=\"kw-bio\">IgD</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Vascularites</span></td>\n            <td>À évoquer systématiquement devant l'association à un <span class=\"kw-clinique\">purpura</span></td>\n            <td>Vaisseaux de moyen calibre → ischémies / <span class=\"kw-clinique\">infarctus</span> intestinaux (risque de perforation) ; atteinte plus distale → ulcérations, hémorragies digestives</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Douleurs rachidiennes projetées</span></td>\n            <td><span class=\"kw-clinique\">Irradiation</span> de la branche antérieure du nerf vertébral</td>\n            <td>Lombalgie associée ; <span class=\"kw-clinique\">zona</span> (rechercher des vésicules de topographie métamérique) ; <span class=\"kw-clinique\">syndrome de Cyriax</span> (subluxation d'une côte flottante → douleur ép<span class=\"kw-chiffre\">iga</span>strique reproduite par la palpation du rebord costal)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Crise vaso-occlusive de drépanocytose</span></td>\n            <td>Patient drépanocytaire connu</td>\n            <td><span class=\"kw-clinique\">Douleur abdominale</span> s'intégrant dans une crise vaso-occlusive</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Phéochromocytome</span></td>\n            <td>Contexte évocateur (poussées hypertensives)</td>\n            <td>Peut donner un tableau abdominal aigu</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Toxiques, médicaments, sevrage</span></td>\n            <td><span class=\"kw-ttt\">Sevrage</span> en <span class=\"kw-ttt\">opiacés</span> ; consommation d'amphétamines, de cocaïne, de dérivés de l'ergot de seigle</td>\n            <td>Le <span class=\"kw-clinique\">sevrage en opiacés</span> donne fréquemment des <span class=\"kw-clinique\">douleurs abdominales</span> aiguës ; <span class=\"kw-clinique\">les</span> vasoconstricteurs (cocaïne, amphétamines, ergot) exposent à une <span class=\"kw-alerte\">ischémie intestinale</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Devant des <span class=\"kw-clinique\">douleurs abdominales</span> intenses avec <span class=\"kw-alerte\">abdomen souple et TR indolore</span>, penser à une cause médicale (insuffisance surrénale aiguë) avant de réopérer ; un <span class=\"kw-alerte\">ECG est systématique</span> devant une douleur ép<span class=\"kw-chiffre\">iga</span>strique avec <span class=\"kw-def\">facteurs de risque</span> cardiovasculaire (<span class=\"kw-etio\">IDM</span> inférieur).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 245 — Insuffisance surrénale · 247 — <span class=\"kw-def\">Diabète</span> · 268 — Hypercalcémie</em></p>","frequence":2},{"id":"269-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître le bilan biologique à prescrire en cas de douleur abdominale aiguë","contenu":"<p>Le bilan <span class=\"kw-ttt\">biologique</span> devant une <span class=\"kw-clinique\">douleur abdominale</span> aiguë comporte un socle <strong>systématique</strong> minimal, complété de manière <strong>orientée</strong> selon le contexte clinique.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Indication</th>\n            <th>Examens</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Systématique</strong></td>\n            <td><span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">CRP</span> — recherche de complications</td>\n          </tr>\n          <tr>\n            <td><strong>Selon le contexte</strong></td>\n            <td>\n              <strong>Femme en âge de procréer :</strong> <span class=\"kw-bio\">β-HCG</span> (éliminer une <span class=\"kw-ci\">grossesse</span> extra-utérine)<br>\n              <strong>Douleur hypochondre droit ou ép<span class=\"kw-chiffre\">iga</span>stre :</strong> <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">lipasémie</span><br>\n              <strong>Signes urinaires :</strong> <span class=\"kw-bio\">bandelette urinaire</span> ± <span class=\"kw-bio\">ECBU</span><br>\n              <strong><span class=\"kw-alerte\">Choc</span> / <span class=\"kw-clinique\">déshydratation</span> / avant <span class=\"kw-imagerie\">TDM</span> :</strong> <span class=\"kw-bio\">ionogramme sanguin</span> ; <span class=\"kw-bio\">créatinine</span> ; <span class=\"kw-bio\">gaz du sang</span> ; <span class=\"kw-bio\">lactatémie</span><br>\n              <strong><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-clinique\">frissons</span> ou <span class=\"kw-clinique\">fièvre</span> &gt; <span class=\"kw-chiffre\">38,5 °C</span> :</strong> <span class=\"kw-bio\">hémocultures</span><br>\n              <strong>Hémorragie digestive / pré-opératoire :</strong> bilan d'hémostase ; groupe-Rh-RAI<br>\n              <strong>Contexte évocateur :</strong> <span class=\"kw-bio\">glycémie</span> ; <span class=\"kw-bio\">calcémie</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5 style=\"margin-top: 1.2em;\"><span class=\"kw-bio\">ECG</span> et <span class=\"kw-bio\">troponine</span></h5>\n      <p><strong>Indication :</strong> <span class=\"kw-clinique\">douleur épigastrique avec facteurs de risque cardiovasculaire</span> ou <span class=\"kw-clinique\">douleur abdominale</span> atypique irradiant vers la poitrine / <span class=\"kw-clinique\">les</span> épaules. <strong>Conduite :</strong> <span class=\"kw-bio\">ECG 17 dérivations</span> + <span class=\"kw-bio\">troponine</span> → recherche d'un <span class=\"kw-etio\">SCA</span> du territoire postérieur.</p>\n\n      <h5 style=\"margin-top: 1.2em;\"><span class=\"kw-imagerie\">Endoscopie</span> œso-gastro-duodénale (<span class=\"kw-imagerie\">EOGD</span>)</h5>\n      <p><strong>Indication :</strong> <span class=\"kw-clinique\">douleur épigastrique aiguë faisant suspecter un ulcère gastro-duodénal</span>. Ni examen <span class=\"kw-ttt\">biologique</span> ni examen d'imagerie, l'<span class=\"kw-imagerie\">EOGD</span> complète le bilan d'une douleur ép<span class=\"kw-chiffre\">iga</span>strique aiguë.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Réflexe paraclinique.</strong> Devant toute <span class=\"kw-clinique\">douleur abdominale</span> aiguë médicale inexpliquée, la fiche insiste sur le trio <span class=\"kw-bio\">ionogramme</span> + <span class=\"kw-bio\">calcémie</span> + <span class=\"kw-bio\">glycémie</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/neonatal-bowel-obstruction","label":"Radiopaedia : Neonatal bowel obstruction"},{"href":"https://radiopaedia.org/articles/pyloric-stenosis-1","label":"Radiopaedia : Pyloric stenosis 1"},{"href":"https://radiopaedia.org/articles/midgut-volvulus","label":"Radiopaedia : Midgut volvulus"},{"href":"https://radiopaedia.org/articles/duodenal-atresia","label":"Radiopaedia : Duodenal atresia"},{"href":"https://radiopaedia.org/articles/hirschsprung-disease","label":"Radiopaedia : Hirschsprung disease"},{"href":"https://radiopaedia.org/articles/inguinal-hernia","label":"Radiopaedia : Inguinal hernia"},{"href":"https://radiopaedia.org/articles/intussusception","label":"Radiopaedia : Intussusception"},{"href":"https://radiopaedia.org/articles/testicular-appendix-1","label":"Radiopaedia : Testicular appendix 1"},{"href":"https://radiopaedia.org/articles/testicular-torsion","label":"Radiopaedia : Testicular torsion"}]},{"id":"269-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une douleur abdominale aiguë de l’adulte","contenu":"<p>Deux examens structurent l'imagerie de la <span class=\"kw-clinique\">douleur abdominale</span> aiguë de l'adulte : l'<span class=\"kw-imagerie\">échographie abdominale</span> et la <span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span>. Leur indication dépend de l'organe suspecté.</p>\n\n      <h5><span class=\"kw-imagerie\">Échographie abdominale</span></h5>\n      <table >\n        <thead>\n          <tr>\n            <th>Utile ✅</th>\n            <th>Inutile ❌</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Suspicion de cause <span class=\"kw-imagerie\">bilio-pancréatique</span> ; cause gynécologique ; cause urinaire ; foyer <span class=\"kw-etio\">infectieux</span> intra-abdominal</td>\n            <td>Syndrome occlusif ; hémorragie digestive ; douleur gastrique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5 style=\"margin-top: 1.2em;\"><span class=\"kw-imagerie\">TDM</span> abdomino-pelvienne injectée</h5>\n      <p>La <span class=\"kw-imagerie\">TDM injectée</span> doit être <strong>privilégiée face à une <span class=\"kw-clinique\">douleur abdominale</span> aiguë inexpliquée</strong>.</p>\n      <table >\n        <thead>\n          <tr>\n            <th>1ʳᵉ intention</th>\n            <th>En <span class=\"kw-bio\">complément</span></th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Suspicion de <span class=\"kw-clinique\">diverticulite</span> s<span class=\"kw-chiffre\">igm</span>oïdienne ; occlusion par obstruction ; syndrome péritonéal</td>\n            <td>Pathologie urogénitale ; syndrome appendiculaire ; <span class=\"kw-etio\">pancréatite aiguë</span> ; <span class=\"kw-clinique\">masse</span> abdominale</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5 style=\"margin-top: 1.2em;\">Imagerie selon la suspicion</h5>\n      <table >\n        <thead>\n          <tr>\n            <th>Suspicion</th>\n            <th>Imagerie</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Cholécystite aiguë</span></td>\n            <td><span class=\"kw-imagerie\">Échographie</span> en 1ʳᵉ intention</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Angiocholite aiguë</span></td>\n            <td><span class=\"kw-imagerie\">Échographie</span> en 1ʳᵉ intention</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Pancréatite aiguë</span></td>\n            <td><span class=\"kw-imagerie\">Échographie</span> à visée étiologique à l'admission (maladie lithiasique) + <span class=\"kw-imagerie\">TDM injectée</span> à visée pronostique à <span class=\"kw-chiffre\">72 h</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Occlusion aiguë</span></td>\n            <td><span class=\"kw-imagerie\">TDM injectée</span> en 1ʳᵉ intention ; <span class=\"kw-imagerie\">ASP</span> à défaut</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Diverticulite aiguë</span></td>\n            <td><span class=\"kw-imagerie\">TDM injectée</span> en 1ʳᵉ intention ; <span class=\"kw-imagerie\">échographie</span> à défaut</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Appendicite aiguë</span></td>\n            <td><span class=\"kw-imagerie\">Échographie</span> en 1ʳᵉ intention ; sauf sujet âgé ± obèse → <span class=\"kw-imagerie\">TDM injectée</span> préférée</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Péritonite</span></td>\n            <td>Diagnostic <span class=\"kw-clinique\">clinique</span> → <span class=\"kw-imagerie\">TDM injectée</span> à visée étiologique ou si doute diagnostique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>À ne pas écrire en QCM.</strong> L'<span class=\"kw-alerte\">ASP (abdomen sans préparation) n'est PAS indiqué</span> chez l'adulte devant une <span class=\"kw-clinique\">douleur abdominale</span> aiguë.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 277 — Lithiase biliaire · 358 — <span class=\"kw-etio\">Pancréatite aiguë</span> · 354 — Syndrome occlusif · 287 — Diverticulose colique - <span class=\"kw-clinique\">diverticulite</span> aiguë · 356 — Appendicite · 357 — Péritonite aiguë</em></p>","frequence":2},{"id":"269-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les caractéristiques de la douleur biliaire, gastrique (duodénale), colique, pancréatique, de l’ischémie intestinale","contenu":"<p>Reconnaître le <strong>profil sémiologique</strong> d'une <span class=\"kw-clinique\">douleur abdominale</span> oriente d'emblée vers l'organe atteint. Tableau comparatif des cinq profils nommés par l'objectif officiel.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Critère</th>\n            <th>Biliaire (<span class=\"kw-clinique\">colique hépatique</span>)</th>\n            <th>Gastrique / duodénale</th>\n            <th>Colique</th>\n            <th>Pancréatique</th>\n            <th>Ischémie intestinale (mésentérique)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Installation / type</strong></td>\n            <td>Brutale, souvent intense, permanente ; <span class=\"kw-clinique\">torsion / spasme / crampe / broiement</span></td>\n            <td><span class=\"kw-clinique\">Crampe / torsion</span></td>\n            <td><span class=\"kw-clinique\">Spasmes qui vont et viennent</span> spontanément ; intensité variable</td>\n            <td><span class=\"kw-clinique\">Crampe / broiement / arrachement</span> ; début rapidement progressif</td>\n            <td>Début <span class=\"kw-alerte\">brutal</span> ; douleur intense et permanente</td>\n          </tr>\n          <tr>\n            <td><strong>Topographie</strong></td>\n            <td>Ép<span class=\"kw-chiffre\">iga</span>stre (<span class=\"kw-chiffre\">50 %</span>) ; hypochondre droit (<span class=\"kw-chiffre\">50 %</span>)</td>\n            <td>Ép<span class=\"kw-chiffre\">iga</span>stre (± hypochondre droit si <span class=\"kw-clinique\">lésion</span> duodénale)</td>\n            <td>Le long du cadre colique, le plus souvent sur un seul segment</td>\n            <td>Ép<span class=\"kw-chiffre\">iga</span>strique « solaire »</td>\n            <td>Péri-ombilicale puis rapidement diffuse à tout l'abdomen</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Irradiation</span></strong></td>\n            <td>Épaule droite ; omoplate droite ; région interscapulaire ; fosse lombaire droite</td>\n            <td><span class=\"kw-alerte\">Pas d'irradiation</span></td>\n            <td>—</td>\n            <td><span class=\"kw-alerte\">Transfixiante en coup de poignard dans le dos</span>, inhibant la respiration</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Facteur aggravant</strong></td>\n            <td>Prise alimentaire ; mise en tension du diaphragme (inspiration, <span class=\"kw-clinique\">toux</span>)</td>\n            <td>Alimentation (douleur du cancer gastrique)</td>\n            <td>Alimentation : déclenche ou aggrave</td>\n            <td>Repas gras ; <span class=\"kw-etio\">alcool</span></td>\n            <td>Repas, si <span class=\"kw-etio\">angor mésentérique</span> chronique annonciateur</td>\n          </tr>\n          <tr>\n            <td><strong>Facteur calmant</strong></td>\n            <td>—</td>\n            <td>Douleur ulcéreuse calmée par l'<strong>alimentation</strong>, <span class=\"kw-clinique\">les</span> pansements gastriques et les antisécrétoires</td>\n            <td>Émission de selles / gaz ; antispasmodiques</td>\n            <td>Position en <span class=\"kw-clinique\">chien de fusil</span> (antéflexion + décubitus latéral gauche) ; jeûne</td>\n            <td>Aucun — <span class=\"kw-alerte\">résistance aux antalgiques</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signe clinique</strong></td>\n            <td><span class=\"kw-clinique\">Signe de Murphy</span> (palpation de l'aire vésiculaire douloureuse à l'inspiration forcée) ; la <span class=\"kw-clinique\">colique hépatique</span> <strong>inhibe l'inspiration forcée</strong></td>\n            <td>Sensibilité ép<span class=\"kw-chiffre\">iga</span>strique ; examen souvent normal</td>\n            <td>Sensibilité / douleur en cadre sur le trajet colique</td>\n            <td><span class=\"kw-alerte\">Très intense, insomniante, résistante aux antalgiques de palier 1-2</span></td>\n            <td><span class=\"kw-alerte\">Contraste douleur intense / examen abdominal pauvre</span> au début ; <span class=\"kw-alerte\">silence auscultatoire</span> possible ; défense ou contracture au <span class=\"kw-def\">stade</span> tardif (<span class=\"kw-clinique\">nécrose</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Manifestations associées</strong></td>\n            <td><span class=\"kw-clinique\">Nausées</span>, <span class=\"kw-clinique\">vomissements</span>. <span class=\"kw-alerte\">Fièvre / frissons ou ictère = orientent d'emblée vers une forme compliquée</span> (<span class=\"kw-clinique\">cholécystite</span>, lithiase de la VBP, angiocholite)</td>\n            <td>—</td>\n            <td>Borborygmes ; ballonnement ; troubles du transit ; émissions glaireuses ou sanglantes</td>\n            <td>PA : <span class=\"kw-clinique\">vomissements</span> alimentaires puis bilieux, <span class=\"kw-clinique\">iléus</span> réflexe. PC : <span class=\"kw-clinique\">amaigrissement</span> + <span class=\"kw-clinique\">diarrhée</span> par <span class=\"kw-clinique\">insuffisance pancréatique exocrine</span></td>\n            <td><span class=\"kw-clinique\">Rectorragies</span> possibles ; au <span class=\"kw-def\">stade</span> tardif <span class=\"kw-alerte\">signes de gravité (choc, défaillance)</span></td>\n          </tr>\n          <tr>\n            <td><strong>Durée / périodicité</strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 6 h si colique hépatique simple</span> (au-delà = forme compliquée)</td>\n            <td>Double périodicité ulcéreuse : douleur post-prandiale tardive (<span class=\"kw-chiffre\">1-3 h</span>) ; poussées de <span class=\"kw-chiffre\">semaines</span> séparées de <span class=\"kw-chiffre\">mois / années</span></td>\n            <td>Crises courtes (<span class=\"kw-chiffre\">1-10 min</span>) ou prolongées (parfois plusieurs heures)</td>\n            <td>Minutes à heures ; prolongée, se termine lentement. <strong>Divergence inter-collège :</strong> LISA → profil évolutif varié (heures à jours) ; MIR → installation rapidement progressive puis permanente</td>\n            <td>Permanente, aggravation progressive — <span class=\"kw-alerte\">urgence vitale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Étiologies</strong></td>\n            <td><span class=\"kw-etio\">Complications de la lithiase biliaire</span> (<span class=\"kw-clinique\">colique hépatique</span>, cholécystite, lithiase VBP, angiocholite) ; cancers de la <span class=\"kw-clinique\">vésicule</span> / VBP.<br><strong>Diag. diff. :</strong> <span class=\"kw-etio\">SCA</span>, <span class=\"kw-clinique\">UGD</span>, <span class=\"kw-etio\">pancréatite aiguë</span></td>\n            <td><span class=\"kw-etio\">Ulcère gastro-duodénal</span> ; <span class=\"kw-etio\">adénocarcinome de l'estomac</span> ; <span class=\"kw-etio\">dyspepsie fonctionnelle</span></td>\n            <td><span class=\"kw-etio\">Syndrome de l'intestin irritable</span> ; <span class=\"kw-etio\">cancer du côlon</span> ; <span class=\"kw-etio\">colites</span> (<span class=\"kw-etio\">MICI</span>, infectieuses, ischémiques, médicamenteuses)</td>\n            <td><span class=\"kw-etio\">Pancréatite aiguë / chronique</span> ; <span class=\"kw-etio\">cancer du pancréas</span> (<span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-clinique\">ictère</span> nu cholestatique)</td>\n            <td><span class=\"kw-etio\">Embolie</span> (AC/FA, post-<span class=\"kw-etio\">IDM</span>) ; <span class=\"kw-etio\">thrombose artérielle</span> sur <span class=\"kw-etio\">athérome</span> mésentérique ; thrombose veineuse mésentérique ; ischémie non occlusive (bas débit)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Ischémie intestinale aiguë — le piège.</strong> Douleur <span class=\"kw-alerte\">intense et permanente contrastant avec un examen abdominal initialement pauvre</span>, sur <span class=\"kw-def\">terrain</span> emboligène (<span class=\"kw-clinique\">AC/FA</span>, post-<span class=\"kw-etio\">IDM</span>) ou <span class=\"kw-etio\">athéromateux</span>. Diagnostic : <span class=\"kw-imagerie\">angio-TDM</span> ; une <span class=\"kw-bio\">hyperlactatémie</span> traduit la souffrance intestinale (<span class=\"kw-alerte\">signe de gravité</span>). <em>Sémiologie extrapolée du Collège HGE (chapitre ischémie mésentérique) — la fiche 269 renvoie au chapitre dédié des pathologies vasculaires digestives pour le détail complet.</em>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé.</strong> Position en <span class=\"kw-clinique\">chien de fusil</span> + <span class=\"kw-clinique\">irradiation</span> transfixiante = pancréatite ; irradiation vers l'<span class=\"kw-clinique\">épaule droite</span> = biliaire ; soulagement par l'<span class=\"kw-clinique\">alimentation</span> = ulcère duodénal ; douleur intense + <span class=\"kw-clinique\">examen abdominal pauvre</span> = ischémie intestinale.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 277 — Lithiase biliaire · 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span> · 303 — Tumeur estomac · 301 — Tumeur colon - rectum · 358 — <span class=\"kw-etio\">Pancréatite aiguë</span> · 281 — <span class=\"kw-def\">Pancréatite chronique</span> · 308 — Tumeur pancréas</em></p>","frequence":4}],"astuces":[],"strategie":{"urgence":"<p><strong>Torsion du cordon spermatique <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> chirurgicale absolue</span></strong></p><p><span class=\"kw-ttt\">exploration chirurgicale</span> immédiate ; l’<span class=\"kw-imagerie\">écho-Doppler</span> ne doit jamais retarder la PEC</p><ul><li>Toute <span class=\"kw-clinique\">douleur testiculaire unilatérale brutale</span> = torsion jusqu’à preuve du contraire</li><li><span class=\"kw-clinique\">Nécrose</span> irréversible si ischémie <span class=\"kw-chiffre\">&gt; 6h</span> (fonction exocrine atteinte dès <span class=\"kw-chiffre\">3–4h</span>, atrophie probable <span class=\"kw-chiffre\">&gt; 24h</span>)</li></ul><p><strong>Volvulus du grêle <span class=\"q\">— nouveau-né / nourrisson</span></strong></p><p>« tout bébé qui vomit vert doit être ouvert » → <span class=\"kw-ttt\">réduction chirurgicale</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li><span class=\"kw-alerte\">Vomissements bilieux (verts)</span> = occlusion mécanique jusqu’à preuve du contraire</li><li>Risque de <span class=\"kw-alerte\">nécrose complète du grêle</span> + <span class=\"kw-alerte\">choc septique</span> ou de grêle court</li></ul><p><strong>Invagination intestinale aiguë <span class=\"q\">— nourrisson <span class=\"kw-chiffre\">2 mois</span> à<span class=\"kw-chiffre\"> 2 ans</span> (pic <span class=\"kw-chiffre\">9 mois</span>)</span></strong></p><p><span class=\"kw-ttt\">lavement</span> (diagnostique + thérapeutique) ; <span class=\"kw-ttt\">chirurgie</span> si échec / complication</p><ul><li>Triade : <span class=\"kw-clinique\">douleurs paroxystiques</span> + <span class=\"kw-clinique\">refus du biberon / vomissements</span> + <span class=\"kw-clinique\">rectorragies « gelée de groseille »</span></li><li><span class=\"kw-imagerie\">Échographie</span> = image en <span class=\"kw-imagerie\">cocarde</span> (transversale) / « sandwich » (longitudinale)</li></ul><p><strong>Ischémie intestinale aiguë <span class=\"q\">— adulte, <span class=\"kw-def\">terrain</span> emboligène</span></strong></p><p><span class=\"kw-imagerie\">angio-TDM</span> en <span class=\"kw-alerte\">urgence</span> (cf. pathologies vasculaires digestives)</p><ul><li><span class=\"kw-alerte\">Douleur intense permanente contrastant avec un examen abdominal pauvre</span></li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">AC/FA</span>, post-<span class=\"kw-etio\">IDM</span>, <span class=\"kw-etio\">athérome mésentérique</span> ; <span class=\"kw-bio\">hyperlactatémie</span> = souffrance intestinale</li></ul><p><strong>Urgences médicales « pseudo-chirurgicales »</strong></p><p>paraclinique systématique : <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">glycémie</span></p><ul><li><span class=\"kw-etio\">IDM inférieur</span> (douleur ép<span class=\"kw-chiffre\">iga</span>strique + <span class=\"kw-clinique\">FRCV</span>) → <span class=\"kw-bio\">ECG</span> systématique + <span class=\"kw-bio\">troponine</span></li><li><span class=\"kw-etio\">Insuffisance surrénale aiguë</span>, <span class=\"kw-etio\">acidocétose diabétique</span>, <span class=\"kw-etio\">hypercalcémie aiguë</span></li></ul>","hospit":"<p><strong>Avis chirurgical / <span class=\"kw-alerte\">hospitalisation</span> urgente</strong></p><p><span class=\"kw-ttt\">mise à jeun</span> + <span class=\"kw-ttt\">hydratation IV</span> + <span class=\"kw-bio\">groupage-Rh-RAI / hémostase</span>, consultation anesthésique</p><ul><li>Signes physiques : <span class=\"kw-alerte\">défense</span>, <span class=\"kw-alerte\">contracture</span>, <span class=\"kw-alerte\">douleur à la décompression</span>, <span class=\"kw-clinique\">masse abdominale</span>, <span class=\"kw-clinique\">tuméfaction inguinale/scrotale douloureuse</span>, plaie pénétrante</li><li>Symptômes : <span class=\"kw-alerte\">vomissements bilieux</span>, <span class=\"kw-alerte\">état de choc</span>, <span class=\"kw-clinique\">déshydratation</span></li></ul><p><strong><span class=\"kw-alerte\">Hospitalisation</span> courte de <span class=\"kw-def\">surveillance</span></strong></p><p><span class=\"kw-def\">surveillance</span> étroite des <span class=\"kw-clinique\">constantes vitales</span> et de la douleur</p><ul><li>Cause non identifiée au 1er bilan, douleur persistante</li><li>Répéter l’<span class=\"kw-clinique\">examen clinique</span>, examens orientés, juger de l’<span class=\"kw-clinique\">évolution</span> immédiate</li></ul><p><strong>Ambulatoire</strong></p><p>rassurer ; <span class=\"kw-alerte\">aucun bilan</span> systématique</p><ul><li><span class=\"kw-etio\">Douleurs abdominales fonctionnelles</span>, <span class=\"kw-etio\">coliques du nourrisson</span> (totalement bénignes)</li><li><span class=\"kw-clinique\">Examen abdominal normal</span>, pas de signe d’alarme, état général conservé</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Vomissements bilieux (verts)</span> → occlusion mécanique / volvulus</li><li><span class=\"kw-alerte\">Défense, contracture, douleur à la décompression</span> → irritation péritonéale</li><li><span class=\"kw-alerte\">Douleur testiculaire / tuméfaction inguinale ou scrotale douloureuse</span> → torsion / hernie étranglée</li><li><span class=\"kw-alerte\">Rectorragies « gelée de groseille »</span>, <span class=\"kw-clinique\">méléna</span>, <span class=\"kw-clinique\">hématémèse</span></li><li><span class=\"kw-alerte\">État de choc</span>, <span class=\"kw-clinique\">déshydratation</span>, instabilité hémodynamique</li><li><span class=\"kw-alerte\">Douleur intense permanente avec examen abdominal pauvre</span> → ischémie intestinale</li><li><span class=\"kw-alerte\">Silence auscultatoire de l’abdomen</span> → strangulation / ischémie / <span class=\"kw-clinique\">iléus</span></li><li><span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-chiffre\">39–40 °C</span> + syndrome péritonéal → <span class=\"kw-etio\">péritonite</span></li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-clinique\">nouveau-né</span>, <span class=\"kw-clinique\">prématuré</span>, <span class=\"kw-clinique\">nourrisson</span> ; contexte de <span class=\"kw-etio\">maltraitance</span> / traumatisme</li><li>Douleur ép<span class=\"kw-chiffre\">iga</span>strique + <span class=\"kw-clinique\">FRCV</span> → <span class=\"kw-etio\">IDM</span> (<span class=\"kw-bio\">ECG</span>)</li></ul>","principes":"<p><strong>Règle d’or :</strong> la priorité est d’identifier <span class=\"kw-clinique\">les</span> situations engageant à court terme le <span class=\"kw-alerte\">pronostic vital ou fonctionnel</span> ; le <span class=\"kw-bio\">bilan paraclinique n’est pas systématique</span>, il est orienté par la clinique ; l’<span class=\"kw-ttt\">antalgie</span> précoce ne masque pas l’examen.</p><p><strong>Mesures symptomatiques / stabilisation</strong></p><ul><li><span class=\"kw-alerte\">Détresse</span> vitale (respiratoire / circulatoire / neurologique) traitée avant tout</li><li><span class=\"kw-ttt\">Remplissage vasculaire</span> si troubles hémodynamiques</li><li><span class=\"kw-ttt\">Antalgiques IV</span> selon l’évaluation de la douleur</li></ul><p><strong>Bilan <span class=\"kw-ttt\">biologique</span> (orienté, non systématique)</strong></p><ul><li>Si <span class=\"kw-clinique\">fièvre</span> / défense : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span> (± <span class=\"kw-bio\">hémocultures</span> si fièvre <span class=\"kw-chiffre\">&gt; 38,5 °C</span>)</li><li>Femme en âge de procréer : <span class=\"kw-bio\">β-hCG</span> (éliminer une <span class=\"kw-etio\">GEU</span>)</li><li>Douleur ép<span class=\"kw-chiffre\">iga</span>stre / HCD : <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">lipasémie</span> ; signes urinaires : <span class=\"kw-bio\">BU</span> ± <span class=\"kw-bio\">ECBU</span></li><li><span class=\"kw-alerte\">Choc</span> / <span class=\"kw-clinique\">déshydratation</span> / avant <span class=\"kw-imagerie\">TDM</span> : <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">GDS</span>, <span class=\"kw-bio\">lactatémie</span> ; contexte évocateur : <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">calcémie</span></li></ul><p><strong>Imagerie</strong></p><p>chez l’enfant : <span class=\"kw-imagerie\">échographie</span> privilégiée, limiter l’<span class=\"kw-clinique\">irradiation</span> (<span class=\"kw-imagerie\">TDM</span> rare)</p><ul><li><span class=\"kw-imagerie\">Échographie</span> en 1re intention : <span class=\"kw-etio\">biliaire</span>, <span class=\"kw-etio\">appendicite</span> (enfant), gynéco/urinaire, <span class=\"kw-etio\">IIA</span>, foyer <span class=\"kw-etio\">infectieux</span></li><li><span class=\"kw-imagerie\">TDM AP injectée</span> : douleur inexpliquée, occlusion, <span class=\"kw-clinique\">diverticulite</span>, péritonite, pancréatite (à <span class=\"kw-chiffre\">72h</span>)</li><li><span class=\"kw-imagerie\">EOGD</span> si suspicion d’ulcère ; <span class=\"kw-ci\">ASP non indiqué chez l’adulte</span> (indications très limitées chez l’enfant)</li></ul><p><strong>Traitement étiologique</strong></p><ul><li>Traiter la cause retrouvée = priorité</li><li>Gestes chirurgicaux selon l’étiologie : <span class=\"kw-ttt\">réduction du volvulus</span>, <span class=\"kw-ttt\">pyloromyotomie</span> (sténose du pylore), <span class=\"kw-ttt\">adhésiolyse</span> (occlusion sur bride), <span class=\"kw-ttt\">orchidopexie</span> (torsion)</li><li><span class=\"kw-ci\">Ne jamais tenter de réduire une hernie de l’ovaire</span> (risque de traumatisme ovarien)</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes","label":"Pedia-univ — Douleurs abdominopelviennes"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur abdominale aiguë — Tri après élimination d’une détresse vitale (respiratoire / circulatoire / neurologique)","detail":"<h4>CAT — douleur abdominale aiguë (< 1 semaine) — Orientation : urgences chirurgicales (enfant + adulte), causes médicales trompeuses, profils d’organe</h4>","branches":[{"to":"t-torsion","label":"Bourse aiguë : douleur testiculaire/scrotale unilatérale brutale (garçon, adolescent, adulte jeune)","color":"red"},{"to":"q-occlusif-age","label":"Syndrome occlusif : arrêt des matières et des gaz, météorisme, ou vomissements bilieux (verts)","color":"red"},{"to":"q-peritoneal-age","label":"Syndrome péritonéal : défense / contracture, fièvre","color":"red"},{"to":"t-ischemie","label":"Douleur intense permanente + examen abdominal pauvre, terrain emboligène/athéromateux (adulte)","color":"red"},{"to":"q-profil","label":"Pas de signe chirurgical — caractériser le profil de la douleur","color":"amber"},{"to":"t-medical","label":"Abdomen souple/indolore contrastant avec une douleur intense (cause médicale trompeuse)","color":"blue"}]},{"id":"t-torsion","kind":"terminal","label":"Torsion du cordon spermatique","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur scrotale unilatérale brutale</span>, intense, continue, souvent nocturne</li><li>Testicule <span class=\"kw-clinique\">dur, ascensionné, rétracté à l’anneau, horizontalisé</span> (signe de Gouverneur)</li><li><span class=\"kw-clinique\">Abolition du réflexe crémastérien</span> ; <span class=\"kw-clinique\">signe de Prehn négatif</span></li></ul><h4>Délai</h4><ul><li><span class=\"kw-clinique\">Nécrose</span> irréversible si ischémie <span class=\"kw-chiffre\">&gt; 6h</span> (fonction exocrine atteinte <span class=\"kw-chiffre\">3–4h</span>, atrophie <span class=\"kw-chiffre\">&gt; 24h</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Exploration chirurgicale</span> en <span class=\"kw-alerte\">urgence</span> : détorsion + <span class=\"kw-ttt\">orchidopexie bilatérale</span> (orchidectomie si testicule non viable)</li><li>L’<span class=\"kw-imagerie\">écho-Doppler</span> peut être faussement rassurant et ne doit jamais retarder la <span class=\"kw-ttt\">chirurgie</span></li></ul>"},{"id":"q-occlusif-age","kind":"decision","label":"Âge du patient ? — Les étiologies de l’occlusion diffèrent radicalement entre l’enfant et l’adulte","branches":[{"to":"t-occl-enfant","label":"Enfant / nourrisson","color":"red"},{"to":"t-occl-adulte","label":"Adulte","color":"red"}]},{"id":"t-occl-enfant","kind":"terminal","label":"Occlusion chirurgicale de l’enfant","color":"red","detail":"<h4>Étiologies selon l’âge</h4><ul><li>Nouveau-né : <span class=\"kw-etio\">atrésie intestinale</span>, <span class=\"kw-etio\">maladie de Hirschsprung</span>, <span class=\"kw-etio\">iléus méconial</span> (révélateur de mucoviscidose)</li><li>Nourrisson : <span class=\"kw-etio\">volvulus du grêle sur malrotation</span>, <span class=\"kw-etio\">sténose hypertrophique du pylore</span>, <span class=\"kw-etio\">invagination intestinale aiguë</span>, <span class=\"kw-etio\">hernie inguinale étranglée</span>, <span class=\"kw-etio\">occlusion sur bride</span></li></ul><h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Vomissements bilieux (verts)</span> = occlusion mécanique jusqu’à preuve du contraire ; arrêt du transit, météorisme</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> : sténose du pylore (cocarde, muscle ≥ <span class=\"kw-chiffre\">4 mm</span>), IIA (cocarde), volvulus (whirlpool sign / signe du tourbillon)</li><li><span class=\"kw-imagerie\">ASP debout</span> ; <span class=\"kw-imagerie\">lavement opaque</span> (orientation Hirschsprung, traitement de l’IIA)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Réhydratation IV</span> + <span class=\"kw-ttt\">SNG en aspiration douce</span> + <span class=\"kw-ttt\">antalgie</span></li><li><span class=\"kw-ttt\">Chirurgie</span> selon la cause : <span class=\"kw-ttt\">réduction du volvulus</span> en <span class=\"kw-alerte\">urgence</span>, <span class=\"kw-ttt\">pyloromyotomie extramuqueuse</span> après correction hydroélectrolytique, <span class=\"kw-ttt\">adhésiolyse</span> si échec médical (bride)</li></ul>"},{"id":"t-occl-adulte","kind":"terminal","label":"Occlusion intestinale aiguë de l’adulte","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur</span> + <span class=\"kw-clinique\">arrêt des matières et des gaz</span> + <span class=\"kw-clinique\">météorisme</span> + <span class=\"kw-clinique\">vomissements</span></li><li><span class=\"kw-alerte\">Silence auscultatoire</span> si strangulation / <span class=\"kw-clinique\">iléus</span> paralytique</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span> en 1re intention (<span class=\"kw-imagerie\">ASP</span> à défaut)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span>, <span class=\"kw-ttt\">SNG</span>, rééquilibration hydroélectrolytique, <span class=\"kw-ttt\">chirurgie</span> selon l’étiologie / si strangulation</li></ul>"},{"id":"q-peritoneal-age","kind":"decision","label":"Âge du patient ?","branches":[{"to":"t-perit-enfant","label":"Enfant / nourrisson","color":"red"},{"to":"t-perit-adulte","label":"Adulte","color":"red"}]},{"id":"t-perit-enfant","kind":"terminal","label":"Péritonite de l’enfant","color":"red","detail":"<h4>Cause</h4><ul><li><span class=\"kw-etio\">Appendicite</span> = 1re cause de <span class=\"kw-clinique\">péritonite</span> chez le nourrisson et l’enfant (toujours compliquée <span class=\"kw-chiffre\">&lt; 6 ans</span>, pic <span class=\"kw-chiffre\">6–15 ans</span>)</li></ul><h4>Clinique</h4><ul><li>Tableau d’occlusion fébrile douloureuse : <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">39–40 °C</span></li><li><span class=\"kw-alerte\">Défense généralisée</span> (petit enfant) / <span class=\"kw-alerte\">contracture abdominale</span> (plus grand)</li><li>Arrêt des matières et des gaz ± <span class=\"kw-clinique\">diarrhée</span> paradoxale</li></ul><h4>Examens</h4><ul><li>Diagnostic clinique ; <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">hémocultures</span> ; <span class=\"kw-imagerie\">échographie</span> (recherche d’<span class=\"kw-clinique\">appendicite</span>) ; <span class=\"kw-ci\">ASP non indiqué</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> en <span class=\"kw-alerte\">urgence</span> + <span class=\"kw-ttt\">antibiothérapie</span></li></ul>"},{"id":"t-perit-adulte","kind":"terminal","label":"Péritonite / appendicite / diverticulite compliquée","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Défense / contracture</span>, syndrome péritonéal, <span class=\"kw-clinique\">fièvre</span></li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-clinique\">Péritonite</span> : diagnostic clinique → <span class=\"kw-imagerie\">TDM injectée</span> à visée étiologique / si doute</li><li><span class=\"kw-clinique\">Appendicite</span> : <span class=\"kw-imagerie\">échographie</span> en 1re intention (<span class=\"kw-imagerie\">TDM injectée</span> si sujet âgé ± obèse)</li><li><span class=\"kw-clinique\">Diverticulite</span> : <span class=\"kw-imagerie\">TDM injectée</span> en 1re intention</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> + <span class=\"kw-ttt\">antibiothérapie</span> selon la cause</li></ul>"},{"id":"t-ischemie","kind":"terminal","label":"Ischémie intestinale aiguë","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Douleur intense et permanente contrastant avec un examen abdominal pauvre</span>, sur <span class=\"kw-def\">terrain</span> emboligène (<span class=\"kw-etio\">AC/FA</span>, post-<span class=\"kw-etio\">IDM</span>) ou <span class=\"kw-etio\">athéromateux</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Angio-TDM</span> en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-bio\">hyperlactatémie</span> = souffrance intestinale (<span class=\"kw-alerte\">signe de gravité</span>)</li></ul><h4>Renvoi</h4><ul><li>Pathologies vasculaires digestives (chapitre dédié)</li></ul>"},{"id":"q-profil","kind":"decision","label":"Profil de la douleur ? — Topographie, irradiation, facteurs aggravants/calmants → organe en cause","branches":[{"to":"t-biliaire","label":"Épigastre/HCD, irradiation épaule droite, aggravée par les repas, signe de Murphy","color":"amber"},{"to":"t-gastro","label":"Épigastrique calmée par l’alimentation, périodicité (post-prandiale tardive)","color":"amber"},{"to":"t-colique","label":"Le long du cadre colique, soulagée par l’émission de selles/gaz","color":"amber"},{"to":"t-pancreas","label":"Épigastrique transfixiante (dos), position en chien de fusil, repas gras/alcool","color":"amber"}]},{"id":"t-biliaire","kind":"terminal","label":"Douleur biliaire (colique hépatique)","color":"amber","detail":"<h4>Clinique</h4><ul><li>Installation <span class=\"kw-clinique\">brutale</span>, intense, <span class=\"kw-clinique\">épigastre / hypochondre droit</span>, <span class=\"kw-clinique\">irradiation</span> <span class=\"kw-clinique\">épaule / omoplate droite</span></li><li>Aggravée par le repas et l’inspiration (inhibe l’inspiration forcée) ; <span class=\"kw-clinique\">signe de Murphy</span> ; durée <span class=\"kw-chiffre\">&lt; 6h</span> si colique simple</li><li><span class=\"kw-clinique\">Fièvre</span> / <span class=\"kw-clinique\">ictère</span> = complication (<span class=\"kw-clinique\">cholécystite</span>, angiocholite)</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> en 1re intention</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Lithiase biliaire</span> et ses complications ; cancers de la <span class=\"kw-clinique\">vésicule</span> / VBP</li></ul><h4>Renvoi</h4><ul><li>Item 277 — Lithiase biliaire</li></ul>"},{"id":"t-gastro","kind":"terminal","label":"Douleur gastro-duodénale (ulcère)","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Crampe épigastrique</span>, sans <span class=\"kw-clinique\">irradiation</span>, <span class=\"kw-clinique\">calmée par la prise alimentaire</span> (ulcère duodénal)</li><li>Double périodicité : post-prandiale tardive (<span class=\"kw-chiffre\">1–3h</span> après <span class=\"kw-clinique\">les</span> repas) ; poussées de quelques semaines</li></ul><h4>Examen</h4><ul><li>Sensibilité ép<span class=\"kw-chiffre\">iga</span>strique, examen parfois normal ; <span class=\"kw-imagerie\">EOGD</span> si suspicion d’ulcère</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Ulcère gastroduodénal</span>, <span class=\"kw-etio\">adénocarcinome de l’estomac</span>, <span class=\"kw-etio\">dyspepsie fonctionnelle</span></li></ul><h4>Renvoi</h4><ul><li>Item 272 — Ulcère gastroduodénal · Item 303 — Tumeur de l’estomac</li></ul>"},{"id":"t-colique","kind":"terminal","label":"Douleur colique","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Spasmes</span> le long du cadre colique, <span class=\"kw-clinique\">soulagés par l’émission de selles / de gaz</span>, aggravés par l’alimentation</li><li>Durée variable (<span class=\"kw-chiffre\">1–10 min</span> ou plusieurs heures) ; troubles du transit associés</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Syndrome de l’intestin irritable</span>, <span class=\"kw-etio\">cancer du côlon</span>, <span class=\"kw-etio\">colites</span> (<span class=\"kw-clinique\">MICI</span>, infectieuses, ischémiques, médicamenteuses)</li></ul><h4>Renvoi</h4><ul><li>Item 301 — Tumeur côlon-rectum</li></ul>"},{"id":"t-pancreas","kind":"terminal","label":"Douleur pancréatique","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Épigastrique « solaire »</span>, <span class=\"kw-clinique\">transfixiante en coup de poignard irradiant dans le dos</span> (inhibe la respiration)</li><li>Très intense, <span class=\"kw-clinique\">insomniante</span>, résistante aux <span class=\"kw-ttt\">antalgiques</span> de palier 1–2</li><li>Soulagée par la <span class=\"kw-clinique\">position en chien de fusil</span> (antéflexion + décubitus latéral gauche) ; déclenchée par repas gras / <span class=\"kw-etio\">alcool</span></li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> à l’admission (lithiase) ; <span class=\"kw-imagerie\">TDM injectée</span> à <span class=\"kw-chiffre\">72h</span> (visée pronostique)</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Pancréatite aiguë</span> (lithiasique, alcoolique)</li></ul><h4>Renvoi</h4><ul><li>Item 358 — <span class=\"kw-clinique\">Pancréatite aiguë</span> · Item 308 — Tumeur du pancréas</li></ul>"},{"id":"t-medical","kind":"terminal","label":"Cause médicale pseudo-chirurgicale","color":"blue","detail":"<h4>Indice</h4><ul><li><span class=\"kw-clinique\">Abdomen souple, TR indolore</span> contrastant avec une douleur intense diffuse → évoquer une cause médicale</li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">IDM inférieur</span> : douleur ép<span class=\"kw-chiffre\">iga</span>strique + <span class=\"kw-clinique\">FRCV</span> → <span class=\"kw-bio\">ECG</span> + <span class=\"kw-bio\">troponine</span> systématiques</li><li><span class=\"kw-etio\">Insuffisance surrénale aiguë</span> : <span class=\"kw-ttt\">corticoïdes</span> interrompus, post-partum ; <span class=\"kw-bio\">hyponatrémie</span>, <span class=\"kw-bio\">hypoglycémie</span></li><li><span class=\"kw-etio\">Acidocétose diabétique</span> : syndrome polyuro-polydipsique, <span class=\"kw-clinique\">dyspnée</span> de Kussmaul, haleine cétosique</li><li><span class=\"kw-etio\">Hypercalcémie aiguë</span> ; <span class=\"kw-etio\">porphyrie aiguë intermittente</span> ; <span class=\"kw-etio\">angio-œdème</span> (<span class=\"kw-ttt\">IEC</span> / <span class=\"kw-ttt\">ARA2</span>)</li></ul><h4>Paraclinique</h4><ul><li>Systématique : <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">glycémie</span></li></ul>"}]},"cards":[{"i":"0aeb4347f92b","n":269,"o":"269-1","u":"Diagnostic positif","t":"Identifier une douleur abdominale chez l’enfant","q":"Quelles sont les causes de « douleurs projetées » abdominales fréquemment rencontrées chez l'enfant ?","a":"<p>Des douleurs projetées abdominales peuvent être causées par :</p><ul><li>Une <strong>pneumopathie de la base</strong>.</li><li>Une <strong>angine</strong>.</li><li>Une <strong>otite</strong>.</li><li>Une <strong>adénolymphite mésentérique</strong>.</li></ul><p>Ces situations nécessitent un examen ORL et pulmonaire complet.</p>"},{"i":"21cfdc5b49ad","n":269,"o":"269-1","u":"Diagnostic positif","t":"Identifier une douleur abdominale chez l’enfant","q":"Comment la douleur abdominale se manifeste-t-elle chez le nourrisson ?","a":"<p>Chez le nourrisson, qui ne verbalise pas, la douleur abdominale se manifeste par :</p><ul><li>Des <strong>accès de pleurs/cris, agitation, irritabilité</strong>.</li><li>Une <strong>pâleur</strong>.</li><li>Un <strong>refus du biberon</strong>.</li><li>Une attitude avec les <strong>jambes repliées sur l'abdomen</strong>.</li><li>Des <strong>troubles du sommeil</strong>.</li></ul>"},{"i":"25db3aee07f4","n":269,"o":"269-1","u":"Diagnostic positif","t":"Identifier une douleur abdominale chez l’enfant","q":"Quels sont les éléments clés à rechercher lors de l'interrogatoire des parents pour caractériser une douleur abdominale chez l'enfant ?","a":"<p>Pour caractériser une douleur abdominale chez l'enfant, il est essentiel de préciser :</p><ul><li>Le <strong>mode d'installation</strong>.</li><li>La <strong>durée</strong> (aiguë &lt; 1 semaine vs récurrente/chronique).</li><li>L'<strong>intensité</strong>.</li><li>Le <strong>siège</strong>.</li><li>L'<strong>irradiation</strong>.</li><li>Les <strong>facteurs déclenchants et calmants</strong>.</li><li>L'<strong>horaire</strong>.</li></ul>"},{"i":"414f3304181e","n":269,"o":"269-1","u":"Diagnostic positif","t":"Identifier une douleur abdominale chez l’enfant","q":"Quelle est la particularité de la localisation de la douleur abdominale chez le jeune enfant ?","a":"<p>Le jeune enfant <strong>montre volontiers la région ombilicale</strong> quelle que soit la cause, ce qui rend cette localisation <strong>peu spécifique</strong> pour le diagnostic différentiel.</p>"},{"i":"82ded6aa2efd","n":269,"o":"269-1","u":"Diagnostic positif","t":"Identifier une douleur abdominale chez l’enfant","q":"Quels sont les éléments indispensables de l'examen clinique de l'abdomen chez l'enfant présentant une douleur ?","a":"<p>Lors de l'examen clinique de l'abdomen chez l'enfant, il est indispensable de :</p><ul><li>Réaliser une <strong>palpation douce</strong> à la recherche d'une <strong>défense ou d'une contracture</strong>, d'une <strong>masse</strong> ou d'une <strong>douleur provoquée</strong>.</li><li>Toujours examiner les <strong>orifices herniaires</strong> et les <strong>bourses</strong> (à la recherche d'une torsion testiculaire).</li><li>Garder en tête que le <strong>toucher rectal n'est pas systématique</strong> chez l'enfant.</li></ul>"},{"i":"c1d816555a57","n":269,"o":"269-1","u":"Diagnostic positif","t":"Identifier une douleur abdominale chez l’enfant","q":"Quels sont les critères d'orientation permettant de distinguer une douleur abdominale organique d'une douleur fonctionnelle chez l'enfant ?","a":"<p>Les critères d'orientation sont :</p><ul><li><strong>Localisation</strong> : Précise et latéralisée (loin de l'ombilic) pour l'organique, péri-ombilicale pour le fonctionnel.</li><li><strong>Irradiation</strong> : Oui pour l'organique, non pour le fonctionnel.</li><li><strong>Rythme</strong> : Continu pour l'organique, sporadique pour le fonctionnel.</li><li><strong>Horaire</strong> : Diurne et nocturne (réveille l'enfant) pour l'organique, diurne (parfois nocturne) pour le fonctionnel.</li><li><strong>AEG</strong> : Souvent présente (perte de poids, retard de croissance/pubertaire) pour l'organique, absente pour le fonctionnel.</li><li><strong>Signes associés</strong> : Diarrhée nocturne, rectorragies, hématémèse, symptômes extra-digestifs (fièvre, arthralgies, rash, aphtes) pour l'organique ; examen abdominal normal et absence de signes associés pour le fonctionnel.</li></ul>"},{"i":"de0d76d15cb3","n":269,"o":"269-1","u":"Diagnostic positif","t":"Identifier une douleur abdominale chez l’enfant","q":"Quels signes d'accompagnement doit-on systématiquement rechercher en cas de douleur abdominale chez l'enfant ?","a":"<p>Les signes d'accompagnement à rechercher systématiquement sont :</p><ul><li>La <strong>fièvre</strong>.</li><li>Les <strong>vomissements</strong> (préciser s'ils sont bilieux).</li><li>Les <strong>troubles du transit</strong> (diarrhée, arrêt des matières et des gaz).</li><li>Les <strong>rectorragies</strong>.</li><li>Les <strong>signes urinaires</strong>.</li><li>Les <strong>signes ORL et respiratoires</strong>.</li></ul>"},{"i":"374eac7dcdb3","n":269,"o":"269-2","u":"Diagnostic positif","t":"Connaître les étiologies des douleurs abdominales chez le nourrisson et l’enfant","q":"Quelles sont les causes chirurgicales et médicales prédominantes de douleur abdominale chez l'enfant (2-12 ans) ?","a":"<p>Chez l'enfant (2-12 ans) :</p><ul><li><strong>Causes chirurgicales :</strong> l'<strong>appendicite aiguë</strong> (1ère cause chirurgicale après 2 ans, pic 7-13 ans, toujours compliquée avant 6 ans), l'<strong>invagination intestinale aiguë</strong> (encore possible), la <strong>hernie étranglée</strong>, le <strong>diverticule de Meckel</strong>, la <strong>torsion testiculaire ou d'annexe</strong>.</li><li><strong>Causes médicales :</strong> la <strong>gastro-entérite aiguë</strong>, l'<strong>adénolymphite mésentérique</strong> (diagnostic différentiel de l'appendicite), la <strong>constipation</strong> (++), les <strong>douleurs abdominales fonctionnelles</strong>, la <strong>pneumopathie de la base</strong>, l'<strong>infection urinaire</strong>, l'<strong>angine</strong>, la <strong>migraine abdominale</strong>, la <strong>crise vaso-occlusive de drépanocytose</strong>, le <strong>purpura rhumatoïde</strong>, l'<strong>acidocétose diabétique</strong>, les <strong>MICI</strong>, la <strong>pancréatite</strong>, le <strong>syndrome hémolytique et urémique</strong>.</li></ul>"},{"i":"6065d88b7f21","n":269,"o":"269-2","u":"Diagnostic positif","t":"Connaître les étiologies des douleurs abdominales chez le nourrisson et l’enfant","q":"Quelles sont les principales causes médicales de douleur abdominale chez le nouveau-né et le nourrisson (1 mois - 2 ans) ?","a":"<p>Chez le nouveau-né et le nourrisson, les principales causes médicales de douleur abdominale sont :</p><ul><li>les <strong>coliques du nourrisson</strong> (bénignes, < 5 mois) ;</li><li>l'<strong>allergie aux protéines de lait de vache</strong> ;</li><li>les <strong>erreurs diététiques</strong> ;</li><li>les <strong>infections</strong> (ORL, urinaire, pulmonaire) ;</li><li>la <strong>gastro-entérite aiguë</strong> (nourrisson) ;</li><li>l'<strong>adénolymphite mésentérique</strong> (nourrisson).</li></ul><p>Il faut toujours suspecter un <strong>traumatisme</strong> (maltraitance) avant l'âge de la marche.</p>"},{"i":"6d8529f9b68e","n":269,"o":"269-2","u":"Diagnostic positif","t":"Connaître les étiologies des douleurs abdominales chez le nourrisson et l’enfant","q":"Quelles sont les principales causes chirurgicales de douleur abdominale chez le nouveau-né (< 1 mois) ?","a":"<p>Chez le nouveau-né, les principales causes chirurgicales de douleur abdominale sont :</p><ul><li>la <strong>hernie inguinale étranglée</strong> ;</li><li>le <strong>volvulus sur malrotation du grêle</strong> ;</li><li>les <strong>occlusions néonatales</strong> (atrésie intestinale, malformation ano-rectale, iléus / bouchon méconial, révélant parfois une mucoviscidose) ;</li><li>la <strong>maladie de Hirschsprung</strong> ;</li><li>l'<strong>entérocolite ulcéro-nécrosante</strong> (ECUN, ++ chez le prématuré).</li></ul>"},{"i":"bed010c3a154","n":269,"o":"269-2","u":"Diagnostic positif","t":"Connaître les étiologies des douleurs abdominales chez le nourrisson et l’enfant","q":"Quelles sont les 5 urgences chirurgicales à éliminer devant toute douleur abdominale chez l'enfant ?","a":"<p>Les 5 urgences chirurgicales à éliminer à tout âge devant une douleur abdominale chez l'enfant sont :</p><ul><li>l'<strong>appendicite</strong> ;</li><li>l'<strong>invagination intestinale aiguë</strong> ;</li><li>la <strong>hernie étranglée</strong> ;</li><li>le <strong>volvulus sur malrotation</strong> ;</li><li>la <strong>torsion testiculaire ou d'annexe</strong>.</li></ul><p>À cela s'ajoute <strong>toute occlusion ou péritonite</strong>.</p>"},{"i":"ff29a11bb118","n":269,"o":"269-2","u":"Diagnostic positif","t":"Connaître les étiologies des douleurs abdominales chez le nourrisson et l’enfant","q":"Quel est le piège diagnostique médical majeur à ne pas oublier face à une douleur abdominale chez l'enfant ?","a":"<p>Le piège diagnostique majeur est l'<strong>acidocétose diabétique</strong>, qui peut se révéler par un tableau pseudo-chirurgical. Une <strong>glycémie capillaire</strong> doit être systématique devant toute douleur abdominale fébrile ou avec des vomissements inexpliqués.</p>"},{"i":"335eb9aec01e","n":269,"o":"269-3","u":"Diagnostic positif","t":"Connaître les examens nécessaires chez l’enfant","q":"Quel est le principe directeur des examens complémentaires chez l'enfant présentant une douleur abdominale aiguë ?","a":"<p>Chez l'enfant, le principe directeur est d'éviter un bilan systématique exhaustif. Les examens sont orientés par la clinique et l'imagerie privilégie les techniques <strong>non irradiantes</strong>.</p>"},{"i":"6fe61657fe01","n":269,"o":"269-3","u":"Diagnostic positif","t":"Connaître les examens nécessaires chez l’enfant","q":"Quels sont les examens d'imagerie de première intention et leurs principales indications devant une douleur abdominale aiguë chez l'enfant ?","a":"<p>L'<strong>échographie abdominale</strong> est l'examen de première intention en raison de son caractère non irradiant. Elle est indiquée pour :</p><ul><li>Appendicite.</li><li>Invagination intestinale aiguë.</li><li>Sténose hypertrophique du pylore.</li><li>Volvulus sur malrotation.</li><li>Torsion testiculaire ou d'annexe.</li><li>Colique néphrétique.</li><li>Bilan de pyélonéphrite (sous 48h).</li><li>Douleurs abdominales récidivantes.</li></ul>"},{"i":"7c6690448689","n":269,"o":"269-3","u":"Diagnostic positif","t":"Connaître les examens nécessaires chez l’enfant","q":"Quels examens biologiques spécifiques sont indiqués et selon quels contextes chez l'enfant avec une douleur abdominale aiguë ?","a":"<ul><li><strong>NFS</strong>, <strong>CRP</strong> si syndrome inflammatoire (ex: appendicite, adénolymphite).</li><li><strong>Ionogramme sanguin</strong> + <strong>créatininémie</strong> si vomissements / déshydratation.</li><li><strong>Bilan hépatique</strong> + <strong>lipasémie</strong> si douleur de l'hypochondre droit ou épigastrique.</li><li><strong>Gaz du sang</strong> si suspicion d'acidocétose.</li></ul>"},{"i":"7c9e508c56cd","n":269,"o":"269-3","u":"Diagnostic positif","t":"Connaître les examens nécessaires chez l’enfant","q":"Quels sont les trois réflexes biologiques à ne pas manquer chez l'enfant présentant une douleur abdominale aiguë ?","a":"<ul><li><strong>Bandelette urinaire</strong> systématique (pour éliminer une infection urinaire).</li><li><strong>Glycémie capillaire ou veineuse</strong> (pour dépister une acidocétose).</li><li><strong>β-HCG</strong> chez l'adolescente.</li></ul>"},{"i":"ea19055ad949","n":269,"o":"269-3","u":"Diagnostic positif","t":"Connaître les examens nécessaires chez l’enfant","q":"Dans quelles situations spécifiques l'ASP (Abdomen Sans Préparation) et la radiographie de thorax sont-ils indiqués chez l'enfant pour une douleur abdominale aiguë ?","a":"<ul><li><strong>ASP</strong>: Indiqué en première intention en cas d'<strong>ingestion de corps étranger radio-opaque</strong>, ou en deuxième intention après échographie si suspicion d'occlusion, de perforation ou de pneumopéritoine.</li><li><strong>Radiographie de thorax</strong>: Indiquée si <strong>polypnée fébrile</strong> ou suspicion de <strong>pneumopathie de la base</strong>.</li></ul>"},{"i":"fbea3abc9d14","n":269,"o":"269-3","u":"Diagnostic positif","t":"Connaître les examens nécessaires chez l’enfant","q":"Quelle est la place de la TDM dans l'exploration d'une douleur abdominale aiguë chez l'enfant ?","a":"<p>La <strong>TDM</strong> doit être limitée en raison de l'irradiation. Elle est réservée aux situations complexes ou en cas de doute persistant après les autres examens.</p>"},{"i":"1fec6a3fbb9d","n":269,"o":"269-4","u":"Identifier une urgence","t":"Identifier une urgence chirurgicale ou médicale chez l’enfant","q":"Quels sont les drapeaux rouges concernant le <strong>terrain</strong> et le <strong>contexte</strong> qui doivent alerter devant une douleur abdominale chez l'enfant ?","a":"<p>Devant une douleur abdominale chez l'enfant, les drapeaux rouges liés au terrain et au contexte sont :</p><ul><li><strong>Terrain</strong> : <ul><li><strong>Prématuré</strong>, <strong>nouveau-né</strong>, <strong>nourrisson</strong>.</li><li><strong>Maladie chronique invalidante</strong>.</li><li><strong>Handicap</strong>.</li></ul></li><li><strong>Contexte</strong> :<ul><li><strong>Traumatisme à haute cinétique</strong>, <strong>chute d'une hauteur élevée</strong>, <strong>polytraumatisme</strong>.</li><li><strong>Suspicion de maltraitance</strong> (traumatisme univoque, surtout avant l'âge de la marche).</li></ul></li></ul>"},{"i":"5b8836ae1294","n":269,"o":"269-4","u":"Identifier une urgence","t":"Identifier une urgence chirurgicale ou médicale chez l’enfant","q":"Quelle doit être l'attitude d'urgence face à des <strong>vomissements bilieux</strong> chez un nourrisson ou une <strong>douleur abdominale chez un garçon</strong> ?","a":"<p>Face à des situations spécifiques, l'attitude d'urgence est :</p><ul><li>Des <strong>vomissements bilieux chez un nourrisson</strong> : doivent faire évoquer une <strong>occlusion / volvulus jusqu'à preuve du contraire</strong>. Cela impose une <strong>imagerie et un avis chirurgical en urgence</strong>.</li><li>Toute <strong>douleur abdominale chez un garçon</strong> : impose un <strong>examen des bourses</strong>, car une <strong>torsion testiculaire</strong> doit être opérée en <strong>moins de 6 heures</strong>.</li></ul>"},{"i":"891a64c7b0fa","n":269,"o":"269-4","u":"Identifier une urgence","t":"Identifier une urgence chirurgicale ou médicale chez l’enfant","q":"Quelles sont les principales <strong>urgences médicales</strong> non chirurgicales pouvant causer une douleur abdominale aiguë chez l'enfant ?","a":"<p>Les principales urgences médicales non chirurgicales pouvant causer une douleur abdominale aiguë chez l'enfant sont :</p><ul><li><strong>Acidocétose diabétique</strong> (la douleur abdominale en est un mode de révélation fréquent).</li><li><strong>Purpura rhumatoïde compliqué</strong> (peut induire une invagination).</li><li><strong>Syndrome hémolytique et urémique</strong> (diarrhée glairo-sanglante puis pâleur + oligurie).</li><li><strong>Sepsis</strong>.</li><li><strong>Insuffisance surrénale aiguë</strong>.</li></ul>"},{"i":"ccbab3e79f45","n":269,"o":"269-4","u":"Identifier une urgence","t":"Identifier une urgence chirurgicale ou médicale chez l’enfant","q":"Quelles sont les principales <strong>urgences chirurgicales</strong> à évoquer devant une douleur abdominale aiguë chez l'enfant ?","a":"<p>Les principales urgences chirurgicales à évoquer devant une douleur abdominale aiguë chez l'enfant sont :</p><ul><li><strong>Appendicite</strong>.</li><li><strong>Invagination intestinale aiguë</strong>.</li><li><strong>Hernie inguinale étranglée</strong>.</li><li><strong>Volvulus sur malrotation</strong>.</li><li><strong>Torsion testiculaire</strong> ou d'annexe.</li><li><strong>Occlusion intestinale</strong>.</li><li><strong>Péritonite</strong>.</li><li><strong>Diverticule de Meckel compliqué</strong>.</li></ul>"},{"i":"e43d689763ae","n":269,"o":"269-4","u":"Identifier une urgence","t":"Identifier une urgence chirurgicale ou médicale chez l’enfant","q":"Quels sont les signes d'alerte à rechercher à l'<strong>examen clinique</strong> devant une douleur abdominale aiguë chez l'enfant ?","a":"<p>À l'examen clinique, les signes d'alerte de gravité devant une douleur abdominale aiguë chez l'enfant sont :</p><ul><li><strong>Défense</strong>, <strong>contracture</strong>.</li><li><strong>Douleur à la décompression</strong>.</li><li><strong>Masse abdominale palpable</strong>.</li><li><strong>Tuméfaction inguinale ou scrotale douloureuse</strong> (hernie non réductible, grosse bourse aiguë).</li><li><strong>Plaie pénétrante</strong>.</li><li><strong>Altération de l'état général</strong> (perte de poids, teint gris, geignement, hypotonie, signes de choc ou de déshydratation).</li><li><strong>Syndrome polyuro-polydipsique</strong>.</li><li><strong>Dyspnée</strong>.</li><li><strong>Signes d'anaphylaxie</strong>.</li><li><strong>Troubles de conscience</strong>.</li></ul>"},{"i":"099415407a05","n":269,"o":"269-5","u":"Identifier une urgence","t":"Connaître les signes cliniques et examens complémentaires en faveur d’une invagination intestinale aiguë","q":"Comment définir cliniquement une invagination intestinale aiguë (IIA) et quelle est sa principale complication en l'absence de traitement ?","a":"<p>L'invagination intestinale aiguë (IIA) est le <strong>télescopage d'un segment intestinal d'amont dans un segment d'aval</strong>. C'est une urgence. En l'absence de traitement, elle peut évoluer vers :</p><ul><li>l'<strong>occlusion</strong>,</li><li>la <strong>nécrose ischémique</strong>,</li><li>la <strong>perforation</strong>,</li><li>le <strong>choc</strong>.</li></ul>"},{"i":"affc3addd777","n":269,"o":"269-5","u":"Identifier une urgence","t":"Connaître les signes cliniques et examens complémentaires en faveur d’une invagination intestinale aiguë","q":"Quels sont les signes cliniques évocateurs d'une invagination intestinale aiguë (IIA) chez le nourrisson ?","a":"<p>La triade classique, rarement complète, inclut :</p><ul><li>des <strong>douleurs paroxystiques</strong> : crises brutales (pleurs, cris, pâleur, hypotonie, refus du biberon, jambes repliées) entrecoupées d'intervalles libres (enfant calme entre les crises),</li><li>des <strong>vomissements</strong> : souvent précoces, d'abord alimentaires,</li><li>des <strong>rectorragies</strong> : sang rouge ou « <strong>gelée de groseille</strong> », signe tardif de souffrance ischémique.</li></ul><p>D'autres signes peuvent être présents :</p><ul><li><strong>somnolence / hypotonie</strong> entre les crises (forme neurologique trompeuse),</li><li><strong>boudin d'invagination palpable</strong> (masse allongée et mobile, inconstant),</li><li>douleur de l'hypochondre droit à la palpation,</li><li><strong>fosse iliaque droite déshabitée</strong> (signe de Dance),</li><li>sang au toucher rectal (non systématique).</li></ul>"},{"i":"f6385d0f5205","n":269,"o":"269-5","u":"Identifier une urgence","t":"Connaître les signes cliniques et examens complémentaires en faveur d’une invagination intestinale aiguë","q":"Quels sont les examens complémentaires clés pour le diagnostic d'une invagination intestinale aiguë (IIA) et quels sont leurs apports ?","a":"<ul><li>L'<strong>échographie abdominale</strong> est l'examen clé de première intention, montrant une <strong>image en cocarde / cible</strong> en coupe transversale ou une <strong>image en sandwich / pseudo-rein</strong> en coupe longitudinale.</li><li>L'abdomen sans préparation (ASP) est peu contributif, pouvant montrer une opacité de l'hypochondre droit ou des signes d'occlusion.</li><li>Le <strong>lavement</strong> (opaque, hydrosoluble ou pneumatique) a une <strong>valeur diagnostique ET thérapeutique</strong>, permettant potentiellement la réduction de l'invagination.</li></ul>"},{"i":"24174eb918d4","n":269,"o":"269-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’interrogatoire et de l’examen clinique face à une douleur abdominale aiguë","q":"Quelles sont les caractéristiques de l'interrogatoire orientant vers une pancréatite en cas de douleur abdominale aiguë ?","a":"<p>La douleur pancréatique est souvent <strong>aggravée par le repas</strong> et <strong>soulagée par l'antéflexion</strong>.</p>"},{"i":"2c719ebbe1fe","n":269,"o":"269-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’interrogatoire et de l’examen clinique face à une douleur abdominale aiguë","q":"Quelle est la signification d'un silence auscultatoire de l'abdomen face à une douleur abdominale aiguë ?","a":"<p>Un silence auscultatoire peut orienter vers une <strong>occlusion par strangulation</strong>, une <strong>ischémie intestinale</strong>, ou un <strong>iléus paralytique</strong>.</p>"},{"i":"35814d34eed7","n":269,"o":"269-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’interrogatoire et de l’examen clinique face à une douleur abdominale aiguë","q":"Quelles sont les caractéristiques sémiologiques d'une douleur abdominale viscérale digestive d'organe creux ?","a":"<ul><li>Elle est le plus souvent localisée à une <strong>région</strong>, rarement à un point précis.</li><li>Elle est volontiers <strong>paroxystique</strong>, à type de <strong>crampes</strong>.</li></ul>"},{"i":"4ab619fbf6cb","n":269,"o":"269-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’interrogatoire et de l’examen clinique face à une douleur abdominale aiguë","q":"Quelle est la signification de bruits hydro-aériques intenses à l'auscultation abdominale face à une douleur abdominale aiguë ?","a":"<p>Des bruits hydro-aériques intenses peuvent indiquer un <strong>obstacle incomplet</strong>, comme dans le syndrome de Koenig.</p>"},{"i":"56089a4afdf9","n":269,"o":"269-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’interrogatoire et de l’examen clinique face à une douleur abdominale aiguë","q":"Quelle est l'irradiation caractéristique d'une douleur de pancréatite aiguë ?","a":"<p>La douleur de pancréatite aiguë irradie typiquement en <strong>postérieur (dos)</strong>, <strong>en ceinture</strong>.</p>"},{"i":"5d322992e17e","n":269,"o":"269-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’interrogatoire et de l’examen clinique face à une douleur abdominale aiguë","q":"Quelles sont les irradiations classiques d'une douleur biliaire (cholécystite, colique hépatique) ?","a":"<p>La douleur biliaire irradie classiquement vers l'<strong>épaule et l'omoplate droite</strong>, via l'innervation du diaphragme par le nerf phrénique.</p>"},{"i":"9c81ecf39979","n":269,"o":"269-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’interrogatoire et de l’examen clinique face à une douleur abdominale aiguë","q":"Comment définit-on une douleur abdominale aiguë en médecine ?","a":"<p>Une douleur abdominale est dite aiguë lorsqu'elle évolue depuis <strong>moins d'une semaine</strong>.</p>"},{"i":"b2f5ec7ebb13","n":269,"o":"269-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’interrogatoire et de l’examen clinique face à une douleur abdominale aiguë","q":"Quelles sont les caractéristiques de l'interrogatoire orientant vers un foyer inflammatoire intra-abdominal irritant le péritoine face à une douleur abdominale aiguë ?","a":"<p>La douleur est <strong>exacerbée</strong> par la marche ou l'inspiration profonde, et <strong>calmée</strong> par le décubitus.</p>"},{"i":"386b4ba6ce6d","n":269,"o":"269-7","u":"Examens complémentaires","t":"Connaître le bilan biologique à prescrire en cas de douleur abdominale aiguë","q":"Quels sont les bilans biologiques complémentaires à considérer en cas de douleur abdominale aiguë chez une femme en âge de procréer ou en cas de douleur épigastrique/hypochondre droit ?","a":"<ul><li>Chez une femme en âge de procréer, il faut systématiquement doser les <strong>β-HCG plasmatiques</strong> pour éliminer une grossesse extra-utérine.</li><li>En cas de douleur de l'hypochondre droit ou épigastrique, il est indiqué de réaliser un <strong>bilan hépatique</strong> et une <strong>lipasémie</strong>.</li></ul>"},{"i":"4a99bc860548","n":269,"o":"269-7","u":"Examens complémentaires","t":"Connaître le bilan biologique à prescrire en cas de douleur abdominale aiguë","q":"Dans quel contexte doit-on prévoir un ECG et un dosage de troponine devant une douleur abdominale aiguë ?","a":"<p>Un <strong>Électrocardiogramme (ECG) 17 dérivations</strong> et un dosage de la <strong>troponine</strong> sont indiqués en cas de <strong>douleur épigastrique avec des facteurs de risque cardiovasculaire</strong>, ou en présence d'une <strong>douleur abdominale atypique irradiant vers la poitrine ou les épaules</strong>, afin de rechercher un syndrome coronarien aigu (SCA) du territoire postérieur.</p>"},{"i":"7ceaf81da41b","n":269,"o":"269-7","u":"Examens complémentaires","t":"Connaître le bilan biologique à prescrire en cas de douleur abdominale aiguë","q":"Quels sont les examens complémentaires à envisager devant une douleur épigastrique aiguë suspectant un ulcère gastro-duodénal ou une douleur abdominale aiguë médicale inexpliquée ?","a":"<ul><li>En cas de douleur épigastrique aiguë suggérant un ulcère gastro-duodénal, une <strong>Endoscopie Œso-Gastro-Duodénale (EOGD)</strong> doit être envisagée.</li><li>Devant toute douleur abdominale aiguë médicale inexpliquée, il est recommandé de réaliser en première intention les examens suivants : <strong>ionogramme sanguin</strong>, <strong>calcémie</strong> et <strong>glycémie</strong>.</li></ul>"},{"i":"be70f1aedcd3","n":269,"o":"269-7","u":"Examens complémentaires","t":"Connaître le bilan biologique à prescrire en cas de douleur abdominale aiguë","q":"Quel est le bilan biologique systématique minimal à réaliser devant une douleur abdominale aiguë ?","a":"<p>Le bilan biologique systématique minimal devant une douleur abdominale aiguë comprend :</p><ul><li>Une <strong>Numération Formule Sanguine (NFS)</strong>.</li><li>Une <strong>Protéine C-Réactive (CRP)</strong>, orientée vers la recherche de complications infectieuses ou inflammatoires.</li></ul>"},{"i":"e6a571ba09f8","n":269,"o":"269-7","u":"Examens complémentaires","t":"Connaître le bilan biologique à prescrire en cas de douleur abdominale aiguë","q":"Quels bilans biologiques et examens sont indiqués en cas de choc, de déshydratation, de signes urinaires, de fièvre ou de suspicion d'hémorragie digestive dans le cadre d'une douleur abdominale aiguë ?","a":"<ul><li>En cas de <strong>choc</strong>, déshydratation, ou avant un scanner, il faut réaliser un <strong>ionogramme sanguin</strong>, une <strong>créatinine</strong>, des <strong>gaz du sang</strong> et une <strong>lactatémie</strong>.</li><li>En présence de <strong>signes urinaires</strong>, une <strong>bandelette urinaire</strong> et potentiellement un <strong>ECBU</strong> (Examen CytoBactériologique des Urines) sont indiqués.</li><li>En cas de <strong>fièvre associée à des frissons</strong> ou une <strong>fièvre > 38,5 °C</strong>, des <strong>hémocultures</strong> sont nécessaires.</li><li>Pour une <strong>hémorragie digestive</strong> ou en pré-opératoire, un <strong>bilan d'hémostase</strong> ainsi qu'un <strong>groupe sanguin, Rhésus et RAI (Recherche d'Agglutinines Irrégulières)</strong> sont demandés.</li></ul>"},{"i":"168f8086bf73","n":269,"o":"269-8","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une douleur abdominale aiguë de l’adulte","q":"Quels sont les deux examens d'imagerie clés à considérer devant une douleur abdominale aiguë chez l'adulte et comment leur indication est-elle déterminée ?","a":"<p>Les deux examens clés sont l'<strong>échographie abdominale</strong> et la <strong>TDM abdomino-pelvienne injectée</strong>. Leur indication dépend principalement de l'<strong>organe suspecté</strong>.</p>"},{"i":"1df955ebc86d","n":269,"o":"269-8","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une douleur abdominale aiguë de l’adulte","q":"Quand la TDM abdomino-pelvienne injectée est-elle privilégiée en première intention ou en complément face à une douleur abdominale aiguë chez l'adulte ?","a":"<p>La TDM injectée est <strong>privilégiée</strong> et souvent de <strong>1<sup>re</sup> intention</strong> face à une <strong>douleur abdominale aiguë inexpliquée</strong>, ou en cas de suspicion de :</p><ul><li><strong>Diverticulite sigmoïdienne</strong>.</li><li><strong>Occlusion par obstruction</strong>.</li><li><strong>Syndrome péritonéal</strong>.</ul><p>Elle est également utilisée en <strong>complément</strong> ou à considérer devant une :</p><ul><li>Pathologie <strong>urogénitale</strong>.</li><li><strong>Syndrome appendiculaire</strong>.</li><li><strong>Pancréatite aiguë</strong>.</li><li><strong>Masse abdominale</strong>.</ul>"},{"i":"232aa4e5971b","n":269,"o":"269-8","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une douleur abdominale aiguë de l’adulte","q":"Quel est le rôle de la TDM injectée en cas de péritonite aiguë ou de forte suspicion clinique ?","a":"<p>En cas de <strong>péritonite</strong> (dont le diagnostic est souvent clinique), la <strong>TDM injectée</strong> est utile à visée <strong>étiologique</strong> ou en cas de <strong>doute diagnostique</strong>.</p><p>Il est important de noter que l'<strong>ASP (abdomen sans préparation) n'est PAS indiqué</strong> chez l'adulte devant une douleur abdominale aiguë.</p>"},{"i":"91507cb62faf","n":269,"o":"269-8","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une douleur abdominale aiguë de l’adulte","q":"Quel examen d'imagerie est recommandé en première intention pour une suspicion de cholécystite aiguë ou d'angiocholite aiguë ?","a":"<p>En cas de suspicion de <strong>cholécystite aiguë</strong> ou d'<strong>angiocholite aiguë</strong>, l'<strong>échographie</strong> est l'examen de <strong>1<sup>re</sup> intention</strong>.</p>"},{"i":"969da40c7e68","n":269,"o":"269-8","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une douleur abdominale aiguë de l’adulte","q":"Quelle est la stratégie d'imagerie pour une pancréatite aiguë ?","a":"<p>Pour une pancréatite aiguë :</p><ul><li>Une <strong>échographie</strong> est réalisée à l'admission à visée <strong>étiologique</strong> (recherche de maladie lithiasique).</li><li>Une <strong>TDM injectée</strong> est effectuée à <strong>72 heures</strong> à visée <strong>pronostique</strong>.</li></ul>"},{"i":"aa591379390e","n":269,"o":"269-8","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une douleur abdominale aiguë de l’adulte","q":"Dans quels contextes cliniques l'échographie abdominale est-elle utile pour explorer une douleur abdominale aiguë chez l'adulte, et quand est-elle considérée comme inutile ?","a":"<p>L'échographie abdominale est considérée comme <strong>utile</strong> en cas de suspicion de :</p><ul><li>Cause <strong>bilio-pancréatique</strong>.</li><li>Cause <strong>gynécologique</strong>.</li><li>Cause <strong>urinaire</strong>.</li><li>Foyer <strong>infectieux intra-abdominal</strong>.</ul><p>Elle est considérée comme <strong>inutile</strong> en cas de :</p><ul><li><strong>Syndrome occlusif</strong>.</li><li><strong>Hémorragie digestive</strong>.</li><li><strong>Douleur gastrique</strong>.</ul>"},{"i":"d49f961cd4c6","n":269,"o":"269-8","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une douleur abdominale aiguë de l’adulte","q":"Quel examen d'imagerie est recommandé en première intention pour une appendicite aiguë, et dans quelles situations la TDM injectée est-elle préférée ?","a":"<p>Pour une <strong>appendicite aiguë</strong>, l'<strong>échographie</strong> est l'examen de <strong>1<sup>re</sup> intention</strong>.</p><p>Cependant, la <strong>TDM injectée</strong> est <strong>préférée</strong> chez le <strong>sujet âgé</strong> et/ou <strong>obèse</strong>.</p>"},{"i":"fffdcda7b3af","n":269,"o":"269-8","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une douleur abdominale aiguë de l’adulte","q":"Quel est l'examen d'imagerie de première intention pour une occlusion aiguë et pour une diverticulite aiguë ?","a":"<p>Pour une <strong>occlusion aiguë</strong>, la <strong>TDM injectée</strong> est l'examen de <strong>1<sup>re</sup> intention</strong> (l'ASP est une alternative à défaut).</p><p>Pour une <strong>diverticulite aiguë</strong>, la <strong>TDM injectée</strong> est également l'examen de <strong>1<sup>re</sup> intention</strong> (l'échographie est une alternative à défaut).</p>"},{"i":"256a4b3fbdc2","n":269,"o":"269-9","u":"Étiologies","t":"Connaître les caractéristiques de la douleur biliaire, gastrique (duodénale), colique, pancréatique, de l’ischémie intestinale","q":"Quelles sont les caractéristiques permettant de différencier la douleur de l'ischémie intestinale aiguë des autres douleurs abdominales aiguës ?","a":"<p>L'ischémie intestinale aiguë se présente avec une <strong>douleur intense et permanente</strong> qui contraste avec un <strong>examen abdominal initialement pauvre</strong>. Elle survient sur un <strong>terrain emboligène</strong> (fibrillation atriale, post-infarctus du myocarde) ou athéromateux. C'est un piège classique car la douleur est très forte mais l'abdomen est peu sensible au début.</p>"},{"i":"44f615377aac","n":269,"o":"269-9","u":"Étiologies","t":"Connaître les caractéristiques de la douleur biliaire, gastrique (duodénale), colique, pancréatique, de l’ischémie intestinale","q":"Quelle est la topographie et l'irradiation de la douleur biliaire (colique hépatique) ?","a":"<p>La douleur biliaire se situe à l'<strong>épigastre (50%)</strong> et/ou à l'<strong>hypochondre droit (50%)</strong>. Elle irradie vers l'<strong>épaule droite, l'omoplate droite, la région interscapulaire ou la fosse lombaire droite</strong>.</p>"},{"i":"45e028f1042e","n":269,"o":"269-9","u":"Étiologies","t":"Connaître les caractéristiques de la douleur biliaire, gastrique (duodénale), colique, pancréatique, de l’ischémie intestinale","q":"Quels sont les facteurs aggravants et calmants de la douleur ulcéreuse gastro-duodénale ?","a":"<ul><li><strong>Facteur aggravant</strong> : alimentation (douleur du cancer gastrique).</li><li><strong>Facteurs calmants</strong> : alimentation, pansements gastriques et antisécrétoires (pour la douleur ulcéreuse).</li></ul>"},{"i":"9e20724d484a","n":269,"o":"269-9","u":"Étiologies","t":"Connaître les caractéristiques de la douleur biliaire, gastrique (duodénale), colique, pancréatique, de l’ischémie intestinale","q":"Quels sont les facteurs aggravants et calmants de la douleur biliaire (colique hépatique) ?","a":"<ul><li><strong>Facteurs aggravants</strong> : la prise alimentaire, la mise en tension du diaphragme (inspiration, toux).</li><li><strong>Facteurs calmants</strong> : aucun.</li></ul>"},{"i":"c4c0077bef41","n":269,"o":"269-9","u":"Étiologies","t":"Connaître les caractéristiques de la douleur biliaire, gastrique (duodénale), colique, pancréatique, de l’ischémie intestinale","q":"Quelle est la topographie et l'irradiation de la douleur pancréatique ?","a":"<p>La douleur pancréatique est <strong>épigastrique « solaire »</strong>. Elle est <strong>transfixiante en coup de poignard dans le dos</strong> et peut <strong>inhiber la respiration</strong>.</p>"},{"i":"ccb66c26275c","n":269,"o":"269-9","u":"Étiologies","t":"Connaître les caractéristiques de la douleur biliaire, gastrique (duodénale), colique, pancréatique, de l’ischémie intestinale","q":"Quelles sont les caractéristiques de l'installation et du type de la douleur biliaire (colique hépatique) ?","a":"<p>La douleur biliaire s'installe de façon <strong>brutale</strong>, est souvent <strong>intense et permanente</strong>. Elle peut être décrite comme une <strong>torsion, un spasme, une crampe ou un broiement</strong>.</p>"},{"i":"ea0efe42c863","n":269,"o":"269-9","u":"Étiologies","t":"Connaître les caractéristiques de la douleur biliaire, gastrique (duodénale), colique, pancréatique, de l’ischémie intestinale","q":"Quelles sont les caractéristiques de l'installation et du type de la douleur gastrique ou duodénale ?","a":"<p>La douleur gastrique ou duodénale se manifeste par des <strong>crampes ou torsions</strong>.</p>"},{"i":"f25df86e5eaa","n":269,"o":"269-9","u":"Étiologies","t":"Connaître les caractéristiques de la douleur biliaire, gastrique (duodénale), colique, pancréatique, de l’ischémie intestinale","q":"Quels sont le signe clinique et les manifestations associées de la douleur biliaire (colique hépatique) ?","a":"<ul><li><strong>Signe clinique</strong> : <strong>Signe de Murphy</strong> (palpation de l'aire vésiculaire douloureuse à l'inspiration forcée) ; la colique hépatique inhibe l'inspiration forcée.</li><li><strong>Manifestations associées</strong> : Nausées, vomissements. La fièvre, frissons ou ictère orientent vers une forme compliquée (cholécystite, lithiase de la VBP, angiocholite).</li></ul>"}]};